import static com.modernchat.feature.MessageHistoryChatFeature.MessageHistoryChatFeatureConfig;

@Slf4j
@Singleton
public class MessageHistoryChatFeature extends AbstractChatFeature<MessageHistoryChatFeatureConfig>
    implements KeyListener {

    @Override
    public String getConfigGroup() {
        return "featureMessageHistory";
    }

    public interface MessageHistoryChatFeatureConfig extends ChatFeatureConfig {
        boolean featureMessageHistory_Enabled();
        int featureMessageHistory_MaxEntries();
        boolean featureMessageHistory_IncludeCommands();
        boolean featureMessageHistory_SkipDuplicates();
        Keybind featureMessageHistory_PrevKey();
        Keybind featureMessageHistory_NextKey();
    }

    private final List<String> history = new ArrayList<>();
    private int navIndex = -1;
    private String stashedDraft = null; // draft before navigation started

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private KeyManager keyManager;
    @Inject private ConfigManager configManager;
    @Inject private Gson gson;
    @Inject private ChatProxy chatProxy;
    @Inject private CommandsChatFeature commandsChatFeature;

    @Inject
    public MessageHistoryChatFeature(ModernChatConfig rootCfg, EventBus eventBus) {
        super(rootCfg, eventBus);
    }

    @Override
    protected MessageHistoryChatFeatureConfig partitionConfig(ModernChatConfig cfg) {
        return new MessageHistoryChatFeatureConfig() {
            @Override public boolean featureMessageHistory_Enabled() { return cfg.featureMessageHistory_Enabled(); }
            @Override public int featureMessageHistory_MaxEntries() { return cfg.featureMessageHistory_MaxEntries(); }
            @Override public boolean featureMessageHistory_IncludeCommands() { return cfg.featureMessageHistory_IncludeCommands();}
            @Override public boolean featureMessageHistory_SkipDuplicates() { return cfg.featureMessageHistory_SkipDuplicates();}
            @Override public Keybind featureMessageHistory_PrevKey() { return cfg.featureMessageHistory_PrevKey();}
            @Override public Keybind featureMessageHistory_NextKey() {return cfg.featureMessageHistory_NextKey(); }
        };
    }

    @Override
    public boolean isEnabled() {
        return config.featureMessageHistory_Enabled();
    }

    @Override
    public void startUp() {
        super.startUp();
        keyManager.registerKeyListener(this);
        resetNavState();
    }

    @Override
    public void shutDown(boolean fullShutdown) {
        super.shutDown(fullShutdown);
        keyManager.unregisterKeyListener(this);
        resetNavState();
        saveHistory();
        history.clear();
    }

    @Override
    public void keyTyped(KeyEvent e) {
    }

    @Override
    public void keyReleased(KeyEvent e) {
    }

    @Override
    public void keyPressed(KeyEvent e) {
        clientThread.invoke(() -> {
            if (ClientUtil.isChatHidden(client))
                return; // don't process keys when chat is hidden

            final Keybind prev = config.featureMessageHistory_PrevKey();
            final Keybind next = config.featureMessageHistory_NextKey();
            final boolean isPrev = prev != null && prev.matches(e);
            final boolean isNext = next != null && next.matches(e);

            if (!isPrev && !isNext)
                return;

            if (!ClientUtil.isChatInputEditable(client))
                return;

            e.consume();

            if (isPrev)
                navigateHistory(-1);
            else
                navigateHistory(+1);
        });
    }

    @Subscribe
    public void onProfileChanged(ProfileChanged e) {
        // When the profile changes, we need to refresh
        loadHistory();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged e) {
        if (e.getGameState() == GameState.LOGGED_IN) {
            // Load history when logging in
            loadHistory();
        } else if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING) {
            // Clear history when logging out
            history.clear();
        }

        resetNavState(); // reset navigation state
    }

    @Subscribe
    public void onChatboxInput(ChatboxInput ev) {
        addHistory(ev.getValue());
    }

    @Subscribe
    public void onNavigateHistoryEvent(NavigateHistoryEvent e) {
        int delta = e.getDelta();
        if (delta == 0) return; // No navigation requested

        clientThread.invoke(() -> navigateHistory(delta));
    }

    @Subscribe
    public void onSubmitHistoryEvent(SubmitHistoryEvent e) {
        if (StringUtil.isNullOrEmpty(e.getText()))
            return;

        addHistory(e.getText());
    }

    private void addHistory(String text) {
        if (text == null) return;

        String msg = Text.removeTags(text).trim();
        if (msg.isEmpty()) return;

        if (commandsChatFeature.isEnabled()) {
            int commandIndex = msg.indexOf(' ');
            if (commandIndex != -1) {
                String cmd = msg.substring(0, commandIndex);
                if (commandsChatFeature.isCommand(cmd.startsWith("/") ? cmd : "/" + cmd)) {
                    // Skip slash commands if configured
                    if (!config.featureMessageHistory_IncludeCommands()) {
                        resetNavState(); // still reset after a send
                        return;
                    }

                    // Ensure it starts with a slash (client trims '/' from messages)
                    if (!msg.startsWith("/"))
                        msg = "/" + msg;
                }
            }
        }

        // Avoid consecutive duplicates if desired
        if (config.featureMessageHistory_SkipDuplicates()
            && !history.isEmpty()
            && history.get(history.size() - 1).equals(msg))
        {
            resetNavState();
            return;
        }

        history.add(msg);

        // Bound the size
        int max = Math.max(1, config.featureMessageHistory_MaxEntries());
        if (history.size() > max)
            history.remove(0);

        saveHistory();
        // After sending, drop navigation state and draft
        resetNavState();
    }

    private void navigateHistory(int delta) {
        if (history.isEmpty()) return;

        // When starting, stash current draft and set index just past newest
        if (navIndex == -1) {
            stashedDraft = chatProxy.getInputText();
            navIndex = history.size();
        }

        if (delta < 0 && navIndex > 0)
            navIndex--;  // older
        else if (delta > 0 && navIndex < history.size())
            navIndex++;  // newer

        if (navIndex >= 0 && navIndex < history.size()) {
            chatProxy.setInputText(history.get(navIndex));
        } else {
            // Past newest, restore the original draft
            String value = stashedDraft != null ? stashedDraft : "";
            clientThread.invoke(() -> {
                chatProxy.setInputText(value);

                if (commandsChatFeature.isEnabled()) {
                    commandsChatFeature.setLastChatInput(value);
                }
            });
        }
    }

    private void loadHistory() {
        try {
            // Per-account configuration
            String json = configManager.getRSProfileConfiguration(ModernChatConfig.GROUP, ModernChatConfig.HISTORY_KEY);
            if (json == null || json.isEmpty()) return;

            Type listType = new TypeToken<List<String>>() {}.getType();
            List<String> saved = gson.fromJson(json, listType);
            if (saved == null) return;

            // apply current cap & sanitize
            int max = Math.max(1, config.featureMessageHistory_MaxEntries());
            List<String> trimmed = saved.stream()
                .filter(s -> s != null && !s.isEmpty())
                .collect(Collectors.toList());

            if (trimmed.size() > max)
                trimmed = trimmed.subList(trimmed.size() - max, trimmed.size());

            history.clear();
            history.addAll(trimmed);
        } catch (Exception ex) {
            log.warn("Failed to load message history", ex);
        }
    }

    private void saveHistory() {
        try {
            int max = Math.max(1, config.featureMessageHistory_MaxEntries());
            List<String> toSave = history;
            if (history.size() > max)
                toSave = history.subList(history.size() - max, history.size());

            String json = gson.toJson(toSave);
            // Per-account configuration
            configManager.setRSProfileConfiguration(ModernChatConfig.GROUP, ModernChatConfig.HISTORY_KEY, json);
        }
        catch (Exception ex) {
            log.warn("Failed to persist message history", ex);
        }
    }

    public void clearHistoryStack() {
        history.clear();
        saveHistory();
    }

    private void resetNavState() {
        navIndex = -1;
        stashedDraft = null;
    }
}

package com.modernchat.feature;

import com.modernchat.ModernChatConfig;
import com.modernchat.ModernChatConfigBase;
import com.modernchat.common.Sfx;
import com.modernchat.event.NotificationEvent;
import com.modernchat.service.SoundService;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

import javax.inject.Inject;
import javax.inject.Singleton;

import static com.modernchat.ModernChatConfigBase.Field.NOTIFY_MESSAGE_RECEIVED_SFX;

@Slf4j
@Singleton
public class NotificationChatFeature extends AbstractChatFeature<NotificationChatFeature.NotificationChatFeatureConfig>
{
    @Override
    public String getConfigGroup() {
        return "featureNotify";
    }

    public interface NotificationChatFeatureConfig extends ChatFeatureConfig {
        boolean featureNotify_Enabled();
        boolean featureNotify_SoundEnabled();
        boolean featureNotify_UseRuneLiteSound();
        int featureNotify_VolumePercent();
        Sfx featureNotify_MessageReceivedSfx();
        boolean featureNotify_OnPublicMessage();
        boolean featureNotify_OnPrivateMessage();
        boolean featureNotify_OnFriendsChat();
        boolean featureNotify_OnClan();
    }

    @Inject private Client client;
    @Inject private Notifier notifier;
    @Inject private SoundService soundService;
    @Inject private AudioPlayer audioPlayer;

    private long lastPlayMs = 0L;

    @Inject
    public NotificationChatFeature(ModernChatConfig config, EventBus eventBus) {
        super(config, eventBus);
    }

    @Override
    protected NotificationChatFeatureConfig partitionConfig(ModernChatConfig config) {
        return new NotificationChatFeatureConfig() {
            @Override public boolean featureNotify_Enabled() { return config.featureNotify_Enabled(); }
            @Override public boolean featureNotify_SoundEnabled() { return config.featureNotify_SoundEnabled(); }
            @Override public boolean featureNotify_UseRuneLiteSound() { return config.featureNotify_UseRuneLiteSound(); }
            @Override public int featureNotify_VolumePercent() { return config.featureNotify_VolumePercent(); }
            @Override public Sfx featureNotify_MessageReceivedSfx() { return config.featureNotify_MessageReceivedSfx(); }
            @Override public boolean featureNotify_OnPublicMessage() { return config.featureNotify_OnPublicMessage(); }
            @Override public boolean featureNotify_OnPrivateMessage() { return config.featureNotify_OnPrivateMessage(); }
            @Override public boolean featureNotify_OnFriendsChat() { return config.featureNotify_OnFriendsChat(); }
            @Override public boolean featureNotify_OnClan() { return config.featureNotify_OnClan(); }
        };
    }

    @Override
    public boolean isEnabled() {
        return config.featureNotify_Enabled();
    }

    @Override
    public void startUp() {
        super.startUp();
    }

    @Override
    public void shutDown(boolean fullShutdown) {
        super.shutDown(fullShutdown);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged e) {
        if (!e.getGroup().startsWith(ModernChatConfigBase.GROUP)) {
            return;
        }

        if (e.getKey().equalsIgnoreCase(NOTIFY_MESSAGE_RECEIVED_SFX.key)) {
            try {
                Sfx sfx = Sfx.valueOf(e.getNewValue());
                playSfxPreview(sfx);
            } catch (Exception ex) {
                log.debug("Preview SFX parse failed for '{}': {}", e.getNewValue(), ex.getMessage());
            }
        }
    }

    @Subscribe
    public void onNotificationEvent(NotificationEvent e) {
        if (!isEnabled())
            return;

        // Filter by chat types
        ChatMessageType type = (ChatMessageType) e.getKey();
        switch (type) {
            case PUBLICCHAT:
                if (!config.featureNotify_OnPublicMessage())
                    return;
                break;
            case PRIVATECHAT:
                if (!config.featureNotify_OnPrivateMessage())
                    return;
                break;
            case FRIENDSCHAT:
            case FRIENDSCHATNOTIFICATION:
                if (!config.featureNotify_OnFriendsChat())
                    return;
                break;
            case CLAN_CHAT:
            case CLAN_GUEST_CHAT:
                if (!config.featureNotify_OnClan())
                    return;
                break;
            default:
                log.debug("Notification ignored for unsupported type: {}", type);
                return;
        }

        if (!e.isAllowSound() || !config.featureNotify_SoundEnabled())
            return;

        // throttle to avoid spam
        long now = System.currentTimeMillis();
        if (now - lastPlayMs < 300)
            return;
        lastPlayMs = now;

        if (config.featureNotify_UseRuneLiteSound()) {
            notifier.notify("New message");
        } else {
            playSfx(config.featureNotify_MessageReceivedSfx(), config.featureNotify_VolumePercent());
        }
    }

    private void playSfxPreview(Sfx sfx) {
        playSfx(sfx, config.featureNotify_VolumePercent());
    }

    private void playSfx(Sfx sfx, int volumePercent) {
        try {
            soundService.play(audioPlayer, sfx, volumePercent);
        } catch (Exception ex) {
            log.debug("Failed to play SFX {}: {}", sfx, ex.toString());
        }
    }
}

