			chatPeekOverlay.dirty();
			chatPeekOverlay.resetFade();
		}
	}

	@Subscribe(priority = -3) // run after ChatMessageManager
	public void onChatMessage(ChatMessage e) {
		// Run message through filter service (replicates ChatFilterPlugin logic internally)
		String filteredMessage = messageFilterService.filterMessage(e);
		if (filteredMessage == null) {
			return; // Message blocked by chat filter plugin
		}

        MessageLine line = ChatUtil.createMessageLine(e, client, false, filteredMessage);
        if (line == null) {
            log.error("Failed to parse chat message event: {}", e);
            return; // Ignore empty messages
        }

        if (!shouldShowMessageForPeekSource(line)) {
            return;
        }

		if (ChatUtil.isIgnoredMessage(line.getText(), line.getType())) {
			log.debug("Ignoring message, type: {}, text: {}", line.getType(), line.getText());
			return;
		}

        log.debug("Chat message received: {}", line);
		chatPeekOverlay.pushLine(line);
	}

	@Subscribe
	public void onSetPeekSourceEvent(SetPeekSourceEvent e) {
		setPeekSource(e.getTabKey());
	}

	@Subscribe
	public void onTabClosedEvent(TabClosedEvent e) {
		String currentSource = config.featurePeek_SourceTabKey();
		if (e.getTabKey().equals(currentSource)) {
			setPeekSource("ALL"); // Default back to All tab
		}
	}

	private boolean shouldShowMessageForPeekSource(MessageLine line) {
		String sourceKey = config.featurePeek_SourceTabKey();
		if (StringUtil.isNullOrEmpty(sourceKey)) {
			return true; // Show all messages when no source is set
		}

		ChatMessageType type = line.getType();
		ChatMode sourceChatMode = getSourceChatMode(sourceKey);

		// First check if message passes the source tab's channel filters
		if (!channelFilterState.shouldShowMessage(type, sourceChatMode)) {
			return false;
		}

		// ALL tab - show everything (that passes filters)
		if (sourceKey.equals("ALL")) {
			return true;
		}

		// GAME tab - game messages only
		if (sourceKey.equals("GAME")) {
			ChannelFilterType filterType = channelFilterState.mapMessageTypeToFilter(type);
			return filterType == ChannelFilterType.GAME;
		}

		// TRADE tab - trade messages only
		if (sourceKey.equals("TRADE")) {
			ChannelFilterType filterType = channelFilterState.mapMessageTypeToFilter(type);
			return filterType == ChannelFilterType.TRADE;
		}

		// Friends Chat tab
		if (sourceKey.equals("FRIENDS_CHAT")) {
			return ChatUtil.isFriendsChatMessage(type);
		}

		// Clan tabs
		if (sourceKey.equals("CLAN_MAIN") || sourceKey.equals("CLAN_GUEST") || sourceKey.equals("CLAN_GIM")) {
			return ChatUtil.isClanMessage(type);
		}

		// Public tab
		if (sourceKey.equals("PUBLIC")) {
			return type == ChatMessageType.PUBLICCHAT || type == ChatMessageType.MODCHAT;
		}

		// Private tab - check target name
		if (sourceKey.startsWith("private_")) {
			String target = sourceKey.substring("private_".length());
			if (!ChatUtil.isPrivateMessage(type)) {
				return false;
			}
			String senderName = line.getSenderName();
			String receiverName = line.getReceiverName();
			return (target.equalsIgnoreCase(senderName)) ||
				   (target.equalsIgnoreCase(receiverName));
		}

		return true; // Default: show message
	}

	/**
	 * Maps a source tab key to the corresponding ChatMode for channel filter lookups.
	 */
	private ChatMode getSourceChatMode(String sourceKey) {
		if (sourceKey == null) {
			return null;
		}
		// Handle private tab keys like "private_Username"
		if (sourceKey.startsWith("private_")) {
			return ChatMode.PRIVATE;
		}
		switch (sourceKey) {
			case "PUBLIC":
				return ChatMode.PUBLIC;
			case "PRIVATE":
				return ChatMode.PRIVATE;
			case "FRIENDS_CHAT":
				return ChatMode.FRIENDS_CHAT;
			case "CLAN_MAIN":
				return ChatMode.CLAN_MAIN;
			case "CLAN_GUEST":
				return ChatMode.CLAN_GUEST;
			case "CLAN_GIM":
				return ChatMode.CLAN_GIM;
			case "GAME":
			case "TRADE":
			case "ALL":
			default:
				// ALL, GAME, TRADE tabs use PUBLIC mode's filters (or null for global)
				return null;
		}
	}

	private void setPeekSource(String tabKey) {
		configManager.setConfiguration(ModernChatConfig.GROUP, ModernChatConfigBase.Keys.featurePeek_SourceTabKey,
			tabKey == null ? "" : tabKey);
		chatPeekOverlay.clearMessages();
		populateFromTabContainer(tabKey);
		chatPeekOverlay.resetFade();
	}

	private void populateFromTabContainer(String tabKey) {
		if (StringUtil.isNullOrEmpty(tabKey)) {
			return;
		}

		MessageContainer container = null;
		if (tabKey.equals("ALL")) {
			container = chatOverlay.getAllContainer();
		} else if (tabKey.equals("GAME")) {
			container = chatOverlay.getGameContainer();
		} else if (tabKey.equals("TRADE")) {
			container = chatOverlay.getTradeContainer();
		} else if (tabKey.startsWith("private_")) {
			String target = tabKey.substring("private_".length());
			container = chatOverlay.getPrivateContainers().get(target);
		} else {
			// Standard tabs: PUBLIC, FRIENDS_CHAT, CLAN_MAIN, CLAN_GUEST, etc.
			container = chatOverlay.getMessageContainers().get(tabKey);
		}

		if (container != null) {
			for (RichLine rl : container.getLines()) {
				chatPeekOverlay.copyLine(rl);
			}
		}
	}

	@Subscribe
	public void onPostClientTick(PostClientTick e) {
		Widget pmWidget = widgetBucket.getPmWidget();
		boolean visible = chatPeekOverlay == null || (chatPeekOverlay.canShow() && config.featurePeek_HideSplitPrivateMessages());
		if (pmWidget != null && visible != pmWidget.isHidden()) {
			pmWidget.setHidden(visible);
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e) {
		if (e.getGroupId() == InterfaceID.CHATBOX) {
			if (chatPeekOverlay != null) {
				chatPeekOverlay.clearChatWidget();
			}
		}
	}

	@Subscribe
	public void onModernChatVisibilityChangeEvent(ModernChatVisibilityChangeEvent e) {
		chatPeekOverlay.setHidden(e.isVisible());
		chatPeekOverlay.resetFade();
	}

	private boolean tryAddClearPeekMessagesMenuOption(MenuEntry[] entries) {
		int order = 0;
		int id = -1;
		for (MenuEntry entry : entries) {
			order++;
			String option = entry.getOption();
			if (option == null || (!option.equalsIgnoreCase("Clear history") &&
								   !option.equalsIgnoreCase("Clear messages")))
				continue;
			id = entry.getIdentifier();
			break;
		}

		if (id == -1)
			return false;

		client.getMenu().createMenuEntry(order - 1)
			.setOption("Clear peek messages")
			.setType(MenuAction.RUNELITE_HIGH_PRIORITY)
			.setIdentifier(0)
			.onClick(me -> chatPeekOverlay.clearMessages());
		return true;
	}

	public void unFade() {
		chatPeekOverlay.resetFade();
	}
}

package com.modernchat.feature;

import com.modernchat.ModernChatConfig;
import com.modernchat.common.ChatProxy;
import com.modernchat.common.WidgetBucket;
import com.modernchat.event.ChatToggleEvent;
import com.modernchat.event.DialogOptionsClosedEvent;
import com.modernchat.event.FeatureStartedEvent;
import com.modernchat.util.ClientUtil;
import com.modernchat.util.GeometryUtil;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.Keybind;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Canvas;
import java.awt.Rectangle;
import java.awt.event.KeyEvent;

import static com.modernchat.feature.ToggleChatFeature.ToggleChatFeatureConfig;

@Slf4j
@Singleton
public class ToggleChatFeature extends AbstractChatFeature<ToggleChatFeatureConfig>
	implements KeyListener
{
	@Override
	public String getConfigGroup() {
		return "featureToggle";
	}

	public interface ToggleChatFeatureConfig extends ChatFeatureConfig
	{
		boolean featureToggle_Enabled();
		Keybind featureToggle_ToggleKey();
		Keybind featureToggle_EscapeHides();
		boolean featureToggle_StartHidden();
		boolean featureToggle_AutoHideOnSend();
		boolean featureToggle_LockCameraWhenVisible();
	}

	private static final int DEFER_HIDE_DELAY_TICKS = 0;   // initial wait before first check
	private static final int DEFER_HIDE_TIMEOUT_TICKS = 5; // give up if input never clears
	public static Rectangle LAST_CHAT_BOUNDS = null;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private KeyManager keyManager;
	@Inject private MouseManager mouseManager;
	@Inject private WidgetBucket widgetBucket;
	@Inject private ChatProxy chatProxy;

	private boolean loggedIn = false;

	// Deferred hide state
	private boolean deferredHideRequested = false;
	private int deferDelayTicksLeft = 0;
	private int deferTimeoutTicksLeft = 0;

	@Inject
	public ToggleChatFeature(ModernChatConfig config, EventBus eventBus) {
		super(config, eventBus);
	}

	@Override
	protected ToggleChatFeatureConfig partitionConfig(ModernChatConfig config) {
		return new ToggleChatFeatureConfig() {
			@Override public boolean featureToggle_Enabled() { return config.featureToggle_Enabled(); }
			@Override public Keybind featureToggle_ToggleKey() { return config.featureToggle_ToggleKey(); }
			@Override public Keybind featureToggle_EscapeHides() { return config.featureToggle_EscapeHides(); }
			@Override public boolean featureToggle_StartHidden() { return config.featureToggle_StartHidden(); }
			@Override public boolean featureToggle_AutoHideOnSend() { return config.featureToggle_AutoHideOnSend(); }
			@Override public boolean featureToggle_LockCameraWhenVisible() { return config.featureToggle_LockCameraWhenVisible(); }
		};
	}

	@Override
	public boolean isEnabled() {
		return config.featureToggle_Enabled();
	}

	@Override
	public void startUp() {
		super.startUp();

		keyManager.registerKeyListener(this);

		if (loggedIn) {
			clientThread.invokeAtTickEnd(() -> setHidden(config.featureToggle_StartHidden()));
		}
	}

	@Override
	public void shutDown(boolean fullShutdown) {
		super.shutDown(fullShutdown);

		keyManager.unregisterKeyListener(this);

		clientThread.invoke(() -> setHidden(false));
	}

	@Override
	public void onFeaturesStarted() {
		super.onFeaturesStarted();

		// We want to register this after all the other features have started,
		// so that it can be overridden.
		keyManager.unregisterKeyListener(this);
		keyManager.registerKeyListener(this);
	}

	@Subscribe
	public void onFeatureStartedEvent(FeatureStartedEvent e) {
		if (e.getFeature().getClass().equals(ChatRedesignFeature.class)) {
			// We need to make sure our key listener is registered after the chat redesign's,
			// so that we don't take priority and consume first.
			keyManager.unregisterKeyListener(this);
			keyManager.registerKeyListener(this);
		}
	}

	@Override
	public void keyTyped(KeyEvent e) {
	}

	@Override
	public void keyReleased(KeyEvent e) {
	}

	@Override
	public void keyPressed(KeyEvent e) {
		if (!chatProxy.isHidden() && config.featureToggle_LockCameraWhenVisible()) {
			switch (e.getKeyCode()) {
				case java.awt.event.KeyEvent.VK_LEFT:
				case java.awt.event.KeyEvent.VK_RIGHT:
				case java.awt.event.KeyEvent.VK_UP:
				case java.awt.event.KeyEvent.VK_DOWN:
					e.consume(); // don’t let the client see the key
					return;
			}
		}

		// Handle the configured hide hotkey before isConsumed check - KeyRemapping
		// consumes Escape when exiting typing mode, but we still need to hide our chat.
		// Do NOT consume the event so the client can still process it (e.g. close interfaces).
		Keybind hideKb = config.featureToggle_EscapeHides();
		if (hideKb != null && !Keybind.NOT_SET.equals(hideKb) && hideKb.matches(e) && !chatProxy.isSystemWidgetActive()) {
			clientThread.invoke(this::hide);
			return;
		}

		Keybind kb = config.featureToggle_ToggleKey();
		if (kb == null || kb.getKeyCode() != e.getKeyCode() || kb.getModifiers() != e.getModifiersEx()) {
			// log out the key event and kb for debugging purposes
			log.debug("KeyPressed: keycode={}, char='{}', modifiers={}, kb={}",
				e.getKeyCode(), e.getKeyChar(), e.getModifiersEx(), kb);
            return;
        }

		// Don't toggle when a system widget is active (dialog, "Enter amount:", etc.)
		// This prevents the deferred toggle from firing after the system input closes.
		if (chatProxy.isSystemWidgetActive()) {
			return;
		}

		if (chatProxy.isCommandMode()) {
			// Don't toggle chat visibility while in command mode
			// We cannot consume the input event
			return;
		}

		clientThread.invokeLater(() -> {
			// If we are currently typing in a system prompt,
			// do not toggle chat visibility.
			if (ClientUtil.isSystemWidgetActive(client)) {
				cancelDeferredHide();
				return;
			}

			// If there is actual text ready to send in chat, defer the hide.
			if (hasPendingChatInputCT()) {
				if (!chatProxy.isHidden() && config.featureToggle_AutoHideOnSend()) {
					scheduleDeferredHide();
				}
				return;
			}

			boolean hidden = !chatProxy.isHidden();
			setHidden(hidden);
		});

		//e.consume();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e) {
		if (e.getGameState() == GameState.LOGGED_IN && !loggedIn) {
			clientThread.invokeLater(() -> {
				// If logging in while a prompt is open, avoid immediate hide
				if (config.featureToggle_StartHidden()) {
					scheduleDeferredHide();
				} else {
					setHidden(false);
				}
			});
			loggedIn = true;
		} else if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING) {
			loggedIn = false;
		}
	}

	@Subscribe
	public void onDialogOptionsClosedEvent(DialogOptionsClosedEvent e) {
		clientThread.invoke(() -> {
			if (chatProxy.isAutoHide() && !chatProxy.isHidden() && chatProxy.isLegacy()) {
				chatProxy.setHidden(true);
			}
		});
	}

	@Subscribe
	public void onGameTick(GameTick tick) {
		handleDeferredHide();
	}

	private boolean handleDeferredHide() {
		if (!deferredHideRequested && !chatProxy.isAutoHide()) {
			return false;
		}

		// If a system prompt appears during deferral, abort the hide
		if (ClientUtil.isSystemWidgetActive(client)) {
			cancelDeferredHide();
			return false;
		} else if (chatProxy.isAutoHide()) {
			chatProxy.setAutoHide(false);
			hide();
			cancelDeferredHide();
			return true;
		}

		// Initial short delay to allow the client to process an Enter press
		if (deferDelayTicksLeft > 0) {
			deferDelayTicksLeft--;
			return false;
		}

		// After delay, wait until the chat input has cleared (message sent)
		Widget chatWidget = widgetBucket.getChatboxViewportWidget();
		if (chatWidget != null) {
			LAST_CHAT_BOUNDS = chatWidget.getBounds();
		}

		boolean isChatBoundsValid = (LAST_CHAT_BOUNDS != null && !GeometryUtil.isInvalidChatBounds(LAST_CHAT_BOUNDS));

		if (!hasPendingChatInputCT() && isChatBoundsValid) {
			hide();
			return true;
		}

		// Still pending; keep waiting up to the timeout
		if (deferTimeoutTicksLeft > 0) {
			deferTimeoutTicksLeft--;
		}
		else if (isChatBoundsValid) {
			// Timed out, do nothing
			cancelDeferredHide();
		}
		return false;
	}

	public void hide() {
		setHidden(true);
	}

	public void show() {
		setHidden(false);
	}

	public void scheduleDeferredHide() {
		deferredHideRequested = true;
		deferDelayTicksLeft = DEFER_HIDE_DELAY_TICKS;
		deferTimeoutTicksLeft = DEFER_HIDE_TIMEOUT_TICKS;
	}

	public void cancelDeferredHide() {
		deferredHideRequested = false;
		deferDelayTicksLeft = 0;
		deferTimeoutTicksLeft = 0;
	}

	private void setHidden(boolean hidden) {
		cancelDeferredHide();

		Widget root = widgetBucket.getChatWidget();
		if (root != null) {
			LAST_CHAT_BOUNDS = root.getBounds();
		}

		boolean wasHidden = chatProxy.isHidden();
		if (wasHidden == hidden)
			return;

		chatProxy.setHidden(hidden);
		eventBus.post(new ChatToggleEvent(hidden));
	}

	private boolean isCanvasFocused() {
		Canvas canvas = client.getCanvas();
		return canvas != null && canvas.hasFocus();
	}

	/** MUST be on client thread: true if the chat input line contains a real message to send. */
	private boolean hasPendingChatInputCT() {
		if (chatProxy.isLegacyHidden())
			return false;

		Widget input = ClientUtil.getChatInputWidget(client);
		if (input == null || input.isHidden())
			return false;

		String raw = input.getText();
		if (raw == null)
			return false;

		String t = Text.removeTags(raw).trim();
		if (t.isEmpty())
			return false;

        // empty chat placeholder
        return !t.endsWith(": *") && !t.endsWith(ClientUtil.PRESS_ENTER_TO_CHAT);
    }

}

package com.modernchat.feature.command;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.input.KeyManager;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import java.awt.event.KeyEvent;

@Slf4j
public abstract class AbstractChatCommand implements CommandsChatFeature.ChatCommandHandler {

    public CommandsChatFeature feature;

    @Inject protected Client client;
    @Inject protected EventBus eventBus;
    @Inject protected KeyManager keyManager;

    @Override
    public void startUp(CommandsChatFeature feature) {
        this.feature = feature;

        eventBus.register(this);
        keyManager.registerKeyListener(this);
    }

    @Override
    public void shutDown(CommandsChatFeature feature) {
        this.feature = null;

        eventBus.unregister(this);
        keyManager.unregisterKeyListener(this);
    }

    @Override
    public void keyTyped(KeyEvent e) {
    }

    @Override
    public void keyPressed(KeyEvent e) {
    }

    @Override
    public void keyReleased(KeyEvent e) {
    }

    protected String getTargetNameFromArgs(String[] args) {
        // Example: /w <name> - whisper to a player
        String arg = args[0].trim();
        if (arg.isEmpty()) {
            log.debug("Invalid target name for /w command");
            return null;
        }

        String target = Text.toJagexName(arg.trim());
        if (target.isEmpty()) {
            log.warn("Invalid target name for /w command");
            return null;
        }

        return target;
    }
}

