    public void setHidden(boolean hidden) {
        if (this.hidden == hidden)
            return; // no change

        if (!hidden && legacyShowing) {
            log.debug("Attempted to show ModernChat while legacy chat is showing, hiding legacy chat first");
            return;
        }

        if (!hidden && ClientUtil.isSystemWidgetActive(client))
            return;

        this.hidden = hidden;

        if (commandMode && !hidden)
            commandMode = false;

        if (hidden) {
            unfocusInput();
            resizePanel.resetCursor();
            // Drop the cached viewport so the container's global mouse listener can't
            // hit-test against a stale rect while the overlay is hidden; render()
            // repopulates it when the overlay is shown again
            if (messageContainer != null)
                messageContainer.clearChatWidget();
        } else {
            focusInput();
        }

        eventBus.post(new ModernChatVisibilityChangeEvent(!this.hidden));
    }

