        // Seems the limit is 80 for all chat modes, so I
        // will leave this here in case it changes in the future
        switch (getCurrentMode()) {
            case PUBLIC:
                return 80;
            case FRIENDS_CHAT:
            case CLAN_MAIN:
            case CLAN_GUEST:
                return 80;
            case CLAN_GIM:
