import java.util.regex.Pattern;

@Slf4j
@Singleton
public class ImageService implements ChatService
{
    public static final Pattern IMG_TAG = Pattern.compile(".*?<img=(\\d+)>\\s*(?:<[^>]+>\\s*)*([^:<>]+?)\\s*:", Pattern.CASE_INSENSITIVE);

    private final Map<Integer, Image> modIconCache = new ConcurrentHashMap<>();
    private BufferedImage filterIcon;

    @Inject private Client client;
    @Inject private SpriteManager spriteManager;

    @Override
    public void startUp() {

    }

    @Override
    public void shutDown() {

    }

    public @Nullable BufferedImage getFilterIcon() {
        if (filterIcon == null) {
            try {
                filterIcon = ImageUtil.loadImageResource(getClass(), "/com/modernchat/images/filter.png");
            } catch (Exception e) {
                log.warn("Failed to load filter icon: {}", e.getMessage());
            }
        }
        return filterIcon;
    }

    public @Nullable Image getModIcon(int id) {
        if (id < 0)
            return null;
        Image cached = modIconCache.get(id);
        if (cached != null)
            return cached;

        IndexedSprite[] icons = client.getModIcons();
        if (icons == null || id >= icons.length)
            return null;

        BufferedImage img = indexedToBufferedImage(icons[id]);
        modIconCache.put(id, img);
        return img;
    }

    public boolean isValidModIcon(int icon) {
        if (icon < 0)
            return false;
        Image cached = modIconCache.get(icon);
        if (cached != null)
            return true;

        IndexedSprite[] icons = client.getModIcons();
        return icons != null && icon < icons.length;
    }

    public static BufferedImage indexedToBufferedImage(IndexedSprite s) {
        if (s == null) return null;

        final int w = s.getWidth();
        final int h = s.getHeight();
        final int[] out = new int[w * h];

        final byte[] pix = s.getPixels();
        final int[] pal  = s.getPalette(); // ARGB-ish ints from the client

        // Note: index 0 is usually transparent in RS sprites
        for (int i = 0; i < pix.length && i < out.length; i++) {
            int idx = pix[i] & 0xFF;
            if (idx == 0) {
                out[i] = 0x00000000; // transparent
            } else {
                int argb = pal[idx];
                // Ensure alpha set (some palettes have 0 alpha)
                if ((argb & 0xFF000000) == 0) argb |= 0xFF000000;
                out[i] = argb;
            }
        }

        BufferedImage bi = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        bi.setRGB(0, 0, w, h, out, 0, w);
        return bi;
    }
}

package com.modernchat.service;

import net.runelite.api.events.ChatMessage;

import javax.annotation.Nullable;

/**
 * Interface for message filters.
 * Filters are applied in order; each receives the possibly-modified text from prior filters.
 */
public interface MessageFilter {

    /**
     * @param message the original ChatMessage (for metadata: type, sender, message node ID)
     * @param currentText the current message text (possibly modified by prior filters)
     * @return filtered text, or {@code null} to block the message entirely
     */
    @Nullable
    String apply(ChatMessage message, String currentText);

    /**
     * @return true if this filter is enabled and should be applied
     */
    default boolean isEnabled() {
        return true;
    }
}

package com.modernchat.service;

import com.modernchat.ModernChatConfig;
import com.modernchat.service.filter.AreaMutePluginFilter;
import com.modernchat.service.filter.ChatFilterPluginFilter;
import com.modernchat.service.filter.SpamCorpusFilter;
import com.modernchat.service.filter.VanillaChatFilter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.EventBus;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Orchestrator service that applies message filters in order.
 */
@Slf4j
@Singleton
public class MessageFilterService implements ChatService {

    @Inject private EventBus eventBus;
    @Inject private ModernChatConfig config;

    @Inject private ChatFilterPluginFilter chatFilterPluginFilter;
    @Inject private AreaMutePluginFilter areaMutePluginFilter;
    @Inject private SpamCorpusFilter spamCorpusFilter;
    @Inject private VanillaChatFilter vanillaChatFilter;

    private final CopyOnWriteArrayList<MessageFilter> filters = new CopyOnWriteArrayList<>();

    @Override
    public void startUp() {
        eventBus.register(this);

        chatFilterPluginFilter.startUp();
        areaMutePluginFilter.startUp();

        registerFilter(vanillaChatFilter);
        registerFilter(chatFilterPluginFilter);
        registerFilter(areaMutePluginFilter);
        registerFilter(spamCorpusFilter);
    }

    @Override
    public void shutDown() {
        eventBus.unregister(this);

        chatFilterPluginFilter.shutDown();
        areaMutePluginFilter.shutDown();

        filters.clear();
    }

    /**
     * Run all registered filters on the given message.
     *
     * @param message the ChatMessage event
     * @return the filtered text, or null if the message should be blocked
     */
    public @Nullable String filterMessage(ChatMessage message) {
        if (!config.filters_Enabled())
            return message.getMessage();

        String text = message.getMessage();
        for (MessageFilter filter : filters) {
            if (!filter.isEnabled())
                continue;

            text = filter.apply(message, text);
            if (text == null)
                return null;
        }
        return text;
    }

    public void registerFilter(MessageFilter filter) {
        filters.addIfAbsent(filter);
    }

    public void unregisterFilter(MessageFilter filter) {
        filters.remove(filter);
    }
}

package com.modernchat.service;

import com.modernchat.common.ChatMode;
import com.modernchat.common.ClanType;
import com.modernchat.event.ChatMessageSentEvent;
import com.modernchat.event.ChatPrivateMessageSentEvent;
import com.modernchat.event.ChatSendLockedEvent;
import com.modernchat.event.SubmitHistoryEvent;
import com.modernchat.util.StringUtil;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.api.gameval.VarClientID;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicInteger;

@Slf4j
@Singleton
public class MessageService implements ChatService
{
    private static final int SEND_COOLDOWN_MS = 900;
    private static final int SEND_HOT_MESSAGE_MAX = 5;
    private static final int SEND_LOCK_MS = 1250;
    private static final int SEND_LOCK_COUNT_RESET_MS = 60000;

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private EventBus eventBus;
    @Inject private FilterService filterService;

    @Getter private volatile long lastSendTimestamp = 0L;
    @Getter private volatile long lastSendLock = 0L;
    @Getter private volatile long sendLockedUntil = 0L;

    private final AtomicInteger sendHotMessageCount = new AtomicInteger(0);
    private final AtomicInteger sendLockCount = new AtomicInteger(0);

    @Override
    public void startUp() {

    }

    @Override
    public void shutDown() {
        lastSendTimestamp = 0L;
    }

    protected void resetLocks() {
        lastSendLock = 0L;
        sendLockedUntil = 0L;
        sendLockCount.set(0);
        sendHotMessageCount.set(0);
    }

    public void sendMessage(String text, ChatMode mode, @Nullable String targetName) {
        if (StringUtil.isNullOrEmpty(text))
            return;

        if (filterService.isFiltered(text))
            return;

        if (processSendLock()) {
            log.debug("Message send is locked, cannot send message: {}", text);
            notifyLocked(targetName, false);
            return;
        }

        // Handle :: commands
        final String trimmed = text.trim();
        if (trimmed.startsWith("::")) {
            clientThread.invoke(() -> {
                client.setVarcStrValue(VarClientID.CHATINPUT, text);
                String typedText = trimmed.substring(2);
                String[] split = typedText.split(" ");
                if (split.length == 0)
                    return;
                String command = split[0];
                String[] args = Arrays.copyOfRange(split, 1, split.length);
                eventBus.post(new CommandExecuted(command, args));
            });
            return;
        }

        ClanType clanType = ClanType.NORMAL; // default clan type
        ChatMode selectedMode = mode;

        switch (mode) {
            case PUBLIC:
                break;
            case FRIENDS_CHAT:
                break;
            case CLAN_MAIN:
            case CLAN_GUEST:
                break;
            case CLAN_GIM:
                clanType = ClanType.IRONMAN;
                break;
            case PRIVATE:
                if (StringUtil.isNullOrEmpty(targetName)) {
                    log.warn("Attempted to send private chat message to no target");
                    return;
                }
                sendPrivateChat(text, targetName);
                return; // skip the rest of the logic
        }

        final int modeValue = selectedMode.getValue();
        final int clanTypeValue = clanType.getValue();

        clientThread.invoke(() -> {
            client.setVarcStrValue(VarClientID.CHATINPUT, text);
            client.runScript(ScriptID.CHAT_SEND, text, modeValue, clanTypeValue, 0, 0);
            eventBus.post(new ChatMessageSentEvent(text, modeValue, clanTypeValue));
        });

        lastSendTimestamp = System.currentTimeMillis();
    }

    public void sendPrivateChat(String text, String targetName) {
        if (StringUtil.isNullOrEmpty(text)) {
            log.warn("Attempted to send empty private chat message");
            return;
        }

        if (StringUtil.isNullOrEmpty(targetName)) {
            log.warn("Attempted to send private chat without a target name");
            return;
        }

        if (filterService.isFiltered(text))
            return;

        if (processSendLock()) {
            log.debug("Private message send is locked, cannot send message: {}", text);
            notifyLocked(targetName, true);
            return;
        }

        clientThread.invoke(() -> {
            client.runScript(ScriptID.PRIVMSG, targetName, text);
            eventBus.post(new SubmitHistoryEvent(text));
            eventBus.post(new ChatPrivateMessageSentEvent(text, targetName));
        });

        lastSendTimestamp = System.currentTimeMillis();
    }

    private void notifyLocked(String targetName, boolean isPrivate) {
        eventBus.post(new ChatSendLockedEvent(targetName, getSendLockedUntil(), isPrivate));
    }

    private boolean processSendLock() {
        if (isSendLocked())
            return true;

        if (!isSendCooldownActive())
            return false;

        sendHotMessageCount.incrementAndGet();
        if (sendHotMessageCount.get() < SEND_HOT_MESSAGE_MAX)
            return false;

        long now = System.currentTimeMillis();
        if (now - lastSendLock >= SEND_LOCK_COUNT_RESET_MS)
            sendLockCount.set(0);

        lastSendLock = now;
        long lockCount = sendLockCount.incrementAndGet();
        long lockDelay = Math.min(lockCount * SEND_LOCK_MS, SEND_LOCK_COUNT_RESET_MS);
        sendLockedUntil = lastSendLock + lockDelay;
        return true;
    }

    public boolean isSendCooldownActive() {
        return System.currentTimeMillis() - lastSendTimestamp < SEND_COOLDOWN_MS;
    }

    public boolean isSendLocked() {
        return System.currentTimeMillis() < sendLockedUntil;
    }
}

package com.modernchat.service;

import com.modernchat.ModernChatConfig;
import com.modernchat.common.ChatMessageBuilder;
import com.modernchat.common.ChatProxy;
import com.modernchat.common.NotificationService;
import com.modernchat.event.ChatSendLockedEvent;
import com.modernchat.util.ClientUtil;
import com.modernchat.util.StringUtil;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.VarClientStr;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.PostClientTick;
import net.runelite.api.events.VarClientStrChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.Keybind;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.awt.event.KeyEvent;
import java.util.Locale;
import java.util.Timer;
import java.util.TimerTask;

@Slf4j
@Singleton
public class PrivateChatService implements ChatService, KeyListener {

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private EventBus eventBus;
    @Inject private KeyManager keyManager;
    @Inject private NotificationService notificationService;
    @Inject private MessageService messageService;
    @Inject private ChatProxy chatProxy;
    @Inject private ModernChatConfig config;

    private volatile String lastPmFrom = null;
    private volatile boolean canShowLockMessage = true;
    @Getter private volatile String lastChatInput;

    // Queue to execute scripts after the frame (avoids reentrancy)
    @Getter
    private String pmTarget = null;
    private String pendingPmTarget = null;
    private String pendingPrefill = null;

    @Override
    public void startUp() {
        eventBus.register(this);
        keyManager.registerKeyListener(this);

        reset();
    }

    @Override
    public void shutDown() {
        eventBus.unregister(this);
        keyManager.unregisterKeyListener(this);

        reset();
    }

    protected void reset() {
        lastPmFrom = null;
        lastChatInput = null;
        pmTarget = null;
        pendingPmTarget = null;
        pendingPrefill = null;
        canShowLockMessage = true;
    }

    @Override
    public void keyTyped(KeyEvent e) {
    }

    @Override
    public void keyReleased(KeyEvent e) {
    }

    @Override
    public void keyPressed(KeyEvent e) {
        Keybind hideKb = config.featureToggle_EscapeHides();
        if (hideKb != null && !Keybind.NOT_SET.equals(hideKb) && hideKb.matches(e)) {
            cancelPrivateMessage();
        } else if (e.getKeyCode() == KeyEvent.VK_ENTER) {
            clientThread.invoke(() -> {
                if (ClientUtil.isSystemTextEntryActive(client)) {
                    String lastInputText = ClientUtil.getSystemInputText(client);
                    if (StringUtil.isNullOrEmpty(lastInputText)) {
                        cancelPrivateMessage();
                    }
                }
            });
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage e) {
        final ChatMessageType t = e.getType();
        if (t == ChatMessageType.PRIVATECHAT || t == ChatMessageType.MODPRIVATECHAT) {
            lastPmFrom = Text.toJagexName(Text.removeTags(e.getName()));
            log.debug("lastPmFrom = {}", lastPmFrom);
        }
    }

    @Subscribe
    public void onVarClientStrChanged(VarClientStrChanged e) {
        if (e.getIndex() != VarClientStr.CHATBOX_TYPED_TEXT)
            return;

        if (chatProxy.isHidden())
            return;

        if (ClientUtil.isSystemTextEntryActive(client))
            return; // Don't do anything if a system prompt is active

        lastChatInput = client.getVarcStrValue(VarClientStr.CHATBOX_TYPED_TEXT);
    }

    @Subscribe
    public void onPostClientTick(PostClientTick e) {
        if (ClientUtil.isSystemTextEntryActive(client)) {
            // If a system prompt is active, don't open PM interface
            return;
        }

        String target = pendingPmTarget;
        if (target == null || target.isEmpty()) {
            target = pmTarget; // Use the current target if no pending
        }

        if (target == null || target.isEmpty()) {
            return;
        }

         if (messageService.isSendLocked()) {
            if (canShowLockMessage) {
                long remainingLock = Math.max(0, messageService.getSendLockedUntil() - System.currentTimeMillis());
                canShowLockMessage = false;
                notificationService.pushChatMessage(new ChatMessageBuilder()
                    .append("You are sending PMs too quickly. Please wait ")
                    .append(Color.RED, String.format(Locale.ROOT, "%.1f", remainingLock / 1000.0))
                    .append(Color.RED, " seconds."));
            }
            return;
        }

        canShowLockMessage = true;

        final String currentTarget = Text.toJagexName(target);
        final String body = pendingPrefill;
        pendingPmTarget = null;
        pendingPrefill = null;

        if (!chatProxy.startPrivateMessage(currentTarget, body, () -> {}))
            setPmTarget(null);
    }

    @Subscribe
    public void onChatSendLockedEvent(ChatSendLockedEvent e) {
        if (!e.isPrivate())
            return;

        var lockDelay = Math.max(0, messageService.getSendLockedUntil() - System.currentTimeMillis());

        String lastPmTarget = getPmTarget();
        cancelPrivateMessage();

        ChatMessageBuilder messageBuilder = new ChatMessageBuilder()
            .append("You are sending PMs too quickly. Please wait ")
            .append(Color.RED, String.format(Locale.ROOT, "%.1f", lockDelay / 1000.0))
            .append(Color.RED, " seconds");

        if (lockDelay < 10000) {
            messageBuilder.append(" (reopening chat momentarily)");
            new Timer().schedule(new TimerTask() {
                @Override
                public void run() {
                    if (StringUtil.isNullOrEmpty(getPmTarget()))
                        setPmTarget(lastPmTarget);
                }
            }, lockDelay);
        }

        notificationService.pushChatMessage(messageBuilder);
    }

    public void setPmTarget(String pmTarget) {
        this.pmTarget = pmTarget;
        canShowLockMessage = true; // Reset lock message state
    }

    public void cancelPrivateMessage() {
        String lastPmTarget = getPmTarget();
        if (lastPmTarget == null || lastPmTarget.isEmpty()) {
            return;
        }

        setPmTarget(null);

        ClientUtil.cancelPrivateMessage(client, clientThread, ()-> {});
    }

    public void replyTo(String target) {
        if (target == null || target.isEmpty()) {
            log.warn("Reply target is empty or null");
            return;
        }

        // Queue for AFTER the frame to avoid "scripts are not reentrant"
        // If something is already queued, don't enqueue again this frame.
        if (pendingPmTarget == null) {
            pendingPmTarget = target;
            pendingPrefill = null; // currently null; kept for future use
        }
    }

    public void replyToLastPm(String body) {
        final String target = lastPmFrom;
        if (target == null || target.isEmpty()) {
            return;
        }

        // Queue for AFTER the frame to avoid "scripts are not reentrant"
        // If something is already queued, don't enqueue again this frame.
        if (pendingPmTarget == null) {
            pendingPmTarget = target;
            pendingPrefill = body; // currently null; kept for future use
        }
    }

    public void clearChatInput() {
        chatProxy.clearInput(()-> {
            lastChatInput = null; // Clear last chat input
        });
    }
}

package com.modernchat.service;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.modernchat.ModernChatConfig;
import com.modernchat.ModernChatConfigBase;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
