import java.awt.Dialog;
import java.awt.FlowLayout;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.FileAlreadyExistsException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

import static com.modernchat.ModernChatConfigBase.DEFAULTS;
import static com.modernchat.ModernChatConfigBase.Field;
import static com.modernchat.ModernChatConfigBase.GROUP;
import static com.modernchat.ModernChatConfigBase.ModernChatProfile;
import static com.modernchat.ModernChatConfigBase.buildJsonFromConfig;
import static com.modernchat.ModernChatConfigBase.setCfg;

@Slf4j
@Singleton
public class ProfileService implements ChatService
{
    @Inject ConfigManager configManager;
    @Inject Gson gson;

    @Getter
    private Path profilesDir;

    /** filename (without .json) -> profile config */
    private final Map<String, ModernChatConfigBase> profiles = new LinkedHashMap<>();

    /** currently active profile key */
    private String activeProfile;

    public ProfileService() {
        this(resolveDefaultProfilesDir());
    }

    public ProfileService(Path profilesDir) {
        this.profilesDir = Objects.requireNonNull(profilesDir);
    }

    public void setProfilesDir(Path profilesDir) { this.profilesDir = Objects.requireNonNull(profilesDir); }

    public Map<String, ModernChatConfigBase> getProfiles() { return Collections.unmodifiableMap(profiles); }

    public Optional<String> getActiveProfileName() { return Optional.ofNullable(activeProfile); }

    public Optional<ModernChatConfigBase> getActiveProfile() {
        return Optional.ofNullable(activeProfile).map(profiles::get);
    }

    /** Set active profile by name; returns true if it exists. */
    public boolean setActiveProfile(String name) {
        if (name == null) return false;
        if (!profiles.containsKey(name)) return false;
        activeProfile = name;
        return true;
    }

    /**
     * Show a custom dialog to choose active profile.
     */
    public Optional<String> chooseActiveProfile(Component parent) {
        if (profiles.isEmpty()) {
            JOptionPane.showMessageDialog(parent,
                "No profiles found in:\n" + profilesDir.toAbsolutePath(),
                "ModernChat Profiles", JOptionPane.WARNING_MESSAGE);
            return Optional.empty();
        }

        final JList<String> list = new JList<>(profiles.keySet().toArray(new String[0]));
        list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        list.setVisibleRowCount(Math.min(8, profiles.size()));
        if (activeProfile != null) list.setSelectedValue(activeProfile, true);

        JPanel panel = new JPanel(new BorderLayout(0, 8));
        panel.setBorder(new EmptyBorder(10, 10, 10, 10));
        panel.add(new JLabel("Select active profile:"), BorderLayout.NORTH);
        panel.add(new JScrollPane(list), BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 8, 0));
        JButton btnSet = new JButton("Set Active");
        JButton btnCancel = new JButton("Cancel");
        buttons.add(btnSet);
        buttons.add(btnCancel);
        panel.add(buttons, BorderLayout.SOUTH);

        final JDialog dialog = new JDialog(
            SwingUtilities.getWindowAncestor(parent),
            "ModernChat Profile",
            Dialog.ModalityType.APPLICATION_MODAL);
        dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        dialog.setContentPane(panel);
        dialog.pack();
        dialog.setLocationRelativeTo(parent);

        final String[] result = new String[1];
        btnSet.addActionListener(ae -> {
            String sel = list.getSelectedValue();
            if (sel != null) result[0] = sel;
            dialog.dispose();
        });
        btnCancel.addActionListener(ae -> {
            result[0] = null;
            dialog.dispose();
        });

        dialog.setVisible(true);

        if (result[0] != null) {
            setActiveProfile(result[0]);
            return Optional.of(result[0]);
        }
        return Optional.empty();
    }

    @Override
    public void startUp() {
        try {
            loadAllProfiles();
            if (profiles.size() == 1) {
                activeProfile = profiles.keySet().iterator().next();
            }
        } catch (IOException e) {
            log.error("[ModernChat] Failed to load profiles: {}", e.getMessage(), e);
        }
    }

    @Override
    public void shutDown() {
    }

    /** Load all *.json files in the profiles directory. */
    public void loadAllProfiles() throws IOException {
        ensureDir(profilesDir);
        profiles.clear();

        try (DirectoryStream<Path> ds = Files.newDirectoryStream(profilesDir, "*.json")) {
            for (Path p : ds) {
                String name = stripExt(p.getFileName().toString());
                ModernChatConfigBase cfg = loadProfile(p);
                if (cfg != null) {
                    profiles.put(name, cfg);
                }
            }
        }
    }

    /** Load a single profile JSON into a ModernChatConfigBase. */
    public ModernChatConfigBase loadProfile(Path file) throws IOException {
        try (BufferedReader br = Files.newBufferedReader(file)) {
            JsonElement root = new JsonParser().parse(br);
            if (root == null || !root.isJsonObject()) {
                throw new IOException("Invalid profile JSON (expecting object): " + file);
            }
            return new ModernChatProfile(root.getAsJsonObject());
        }
    }

    public void applyActiveProfileToConfig() {
        ModernChatConfigBase cfg = getActiveProfile().orElse(DEFAULTS);
        applyProfileToConfig(configManager, cfg);
    }

    public static void applyProfileToConfig(ConfigManager cm, ModernChatConfigBase cfg) {
        for (Field k : ModernChatConfigBase.Field.values()) {
            if (k.key.equals(Field.FEATURE_EXAMPLE.key))
                continue; // skip example feature, not a real config key

            Object v = k.read(cfg);
            setCfg(cm, GROUP, k.key, v);
        }
    }

    public void saveCurrentToProfile(ConfigManager cm, String profileName) throws IOException {
        if (profileName == null || profileName.trim().isEmpty())
            throw new IllegalArgumentException("profileName is empty");

        ModernChatConfigBase cfg = cm.getConfig(ModernChatConfig.class); // reads live RL values
        saveProfile(profileName.trim(), cfg);
    }

    public void saveCurrentAsNewProfile(ConfigManager cm, String profileName) throws IOException {
        if (profileName == null || profileName.trim().isEmpty())
            throw new IllegalArgumentException("profileName is empty");

        ModernChatConfigBase cfg = cm.getConfig(ModernChatConfig.class);
        saveProfile(profileName.trim(), cfg, true);
    }

    public void saveProfile(String profileName, ModernChatConfigBase cfg) throws IOException {
        saveProfile(profileName, cfg, false);
    }

    private void saveProfile(String profileName, ModernChatConfigBase cfg, boolean failIfExists) throws IOException {
        ensureDir(profilesDir);
        Path out = profilesDir.resolve(profileName + ".json");

        if (failIfExists && Files.exists(out))
            throw new FileAlreadyExistsException(out.toString());

        JsonObject root = buildJsonFromConfig(cfg);
        var gsonPretty = gson.newBuilder().setPrettyPrinting().create();
        try (var w = Files.newBufferedWriter(out, StandardCharsets.UTF_8,
            StandardOpenOption.CREATE, failIfExists ? StandardOpenOption.CREATE_NEW : StandardOpenOption.TRUNCATE_EXISTING,
            StandardOpenOption.WRITE))
        {
            gsonPretty.toJson(root, w);
        }
    }

    private static void ensureDir(Path dir) throws IOException {
        if (!Files.exists(dir))
            Files.createDirectories(dir);
        if (!Files.isDirectory(dir))
            throw new IOException("Not a directory: " + dir);
    }

    private static String stripExt(String fn) {
        int i = fn.lastIndexOf('.');
        return (i > 0 ? fn.substring(0, i) : fn);
    }

    private static Path resolveDefaultProfilesDir() {
        Path rlHome;
        try {
            rlHome = RuneLite.RUNELITE_DIR.toPath();
        } catch (Throwable ignored) {
            rlHome = Paths.get(System.getProperty("user.home", ".")).resolve(".runelite");
        }
        return rlHome.resolve("modern-chat");
    }
}

package com.modernchat.service;

import com.modernchat.common.LazyLoad;
import com.modernchat.common.Sfx;
import com.modernchat.util.MathUtil;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

import javax.inject.Singleton;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.util.Map;

import static java.util.Map.entry;

@Slf4j
@Singleton
public class SoundService implements ChatService
{
    private static final String BASE_PATH = "/com/modernchat/sounds/";

    private Map<Sfx, LazyLoad<byte[]>> defaultSounds = null;

    @Override
    public void startUp() {
        defaultSounds = Map.ofEntries(
            entry(Sfx.MSG_RECEIVED_1, lazyLoadBytes(BASE_PATH + "message_received_1.wav")),
            entry(Sfx.MSG_RECEIVED_2, lazyLoadBytes(BASE_PATH + "message_received_2.wav")),
            entry(Sfx.MSG_RECEIVED_3, lazyLoadBytes(BASE_PATH + "message_received_3.wav")),
            entry(Sfx.MSG_RECEIVED_4, lazyLoadBytes(BASE_PATH + "message_received_4.wav"))
        );
    }

    @Override
    public void shutDown() {
        defaultSounds = null;
    }

    public void play(AudioPlayer player, Sfx sfx, int volumePercent) {
        if (player == null)
            return;

        byte[] data = getSoundBytes(sfx);
        if (data == null || data.length == 0) {
            log.debug("No audio data for SFX {}", sfx);
            return;
        }
        float volume = MathUtil.clamp01(volumePercent / 100f);
        try {
            player.play(new ByteArrayInputStream(data), volume);
        } catch (Throwable t) {
            log.debug("Failed to play SFX {}: {}", sfx, t.toString());
        }
    }

    private LazyLoad<byte[]> lazyLoadBytes(String resourcePath) {
        return new LazyLoad<>(() -> {
            try {
                return loadBytes(resourcePath);
            } catch (Exception e) {
                throw new RuntimeException("Failed to load sound bytes: " + resourcePath, e);
            }
        });
    }

    private byte[] loadBytes(String resourcePath) throws Exception {
        try (InputStream in = getClass().getResourceAsStream(resourcePath)) {
            if (in == null) {
                throw new IllegalStateException("Missing sound resource: " + resourcePath);
            }
            ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(4096, in.available()));
            byte[] buf = new byte[8192];
            int n;
            while ((n = in.read(buf)) >= 0) {
                out.write(buf, 0, n);
            }
            return out.toByteArray();
        }
    }

    private byte[] getSoundBytes(Sfx sound) {
        if (defaultSounds == null) {
            throw new IllegalStateException("SoundService not started up yet");
        }
        LazyLoad<byte[]> lazy = defaultSounds.get(sound);
        if (lazy == null) {
            log.debug("Unknown SFX {}; available: {}", sound, defaultSounds.keySet());
            return null;
        }
        return lazy.get();
    }
}

package com.modernchat.service;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import javax.inject.Singleton;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Service for managing user-defined spam/ham corpus for chat filtering.
 * Allows users to mark messages as spam or ham (not spam) to build
 * a personal filter list.
 *
 * Uses the same corpus files as SpamFilterPlugin for compatibility.
 */
@Slf4j
@Singleton
public class SpamFilterService implements ChatService
{
    // Use same directory and file names as SpamFilterPlugin for compatibility
    private static final String SPAMFILTER_DIR = "spam-filter";
    private static final String SPAM_CORPUS_FILE = "user_bad_corpus.txt";
    private static final String HAM_CORPUS_FILE = "user_good_corpus.txt";

    private Path dataDir;
    private Path spamCorpusFile;
    private Path hamCorpusFile;

    @Getter
    private final List<String> spamCorpus = new ArrayList<>();
    @Getter
    private final List<String> hamCorpus = new ArrayList<>();

    @Override
    public void startUp() {
        dataDir = resolveDataDir();
        spamCorpusFile = dataDir.resolve(SPAM_CORPUS_FILE);
        hamCorpusFile = dataDir.resolve(HAM_CORPUS_FILE);

        try {
            ensureDir(dataDir);
            loadCorpus(spamCorpusFile, spamCorpus);
            loadCorpus(hamCorpusFile, hamCorpus);
            log.debug("SpamFilterService started - loaded {} spam entries, {} ham entries",
                spamCorpus.size(), hamCorpus.size());
        } catch (IOException e) {
            log.error("Failed to initialize spam filter service", e);
        }
    }

    @Override
    public void shutDown() {
        // Corpus is saved on each modification, no action needed here
    }

    /**
     * Mark a message as spam. Adds it to the spam corpus.
     *
     * @param message the message text to mark as spam
     */
    public void markSpam(String message) {
        if (message == null || message.isEmpty()) {
            return;
        }

        String cleanMessage = cleanMessage(message);
        appendToCorpus(cleanMessage, spamCorpus, spamCorpusFile);
        log.debug("Marked as spam: {}", cleanMessage);
    }

    /**
     * Mark a message as ham (not spam). Adds it to the ham corpus.
     *
     * @param message the message text to mark as ham
     */
    public void markHam(String message) {
        if (message == null || message.isEmpty()) {
            return;
        }

        String cleanMessage = cleanMessage(message);
        appendToCorpus(cleanMessage, hamCorpus, hamCorpusFile);
        log.debug("Marked as ham: {}", cleanMessage);
    }

    /**
     * Check if a message is in the spam corpus.
     *
     * @param message the message to check
     * @return true if the message is marked as spam
     */
    public boolean isMarkedSpam(String message) {
        if (message == null || message.isEmpty()) {
            return false;
        }
        String cleanMessage = cleanMessage(message);
        return spamCorpus.contains(cleanMessage);
    }

    /**
     * Check if a message is in the ham corpus.
     *
     * @param message the message to check
     * @return true if the message is marked as ham
     */
    public boolean isMarkedHam(String message) {
        if (message == null || message.isEmpty()) {
            return false;
        }
        String cleanMessage = cleanMessage(message);
        return hamCorpus.contains(cleanMessage);
    }

    /**
     * Remove a message from the spam corpus.
     *
     * @param message the message to remove
     * @return true if the message was removed
     */
    public boolean removeFromSpam(String message) {
        if (message == null || message.isEmpty()) {
            return false;
        }
        String cleanMessage = cleanMessage(message);
        boolean removed = spamCorpus.remove(cleanMessage);
        if (removed) {
            saveCorpus(spamCorpusFile, spamCorpus);
            log.debug("Removed from spam corpus: {}", cleanMessage);
        }
        return removed;
    }

    /**
     * Remove a message from the ham corpus.
     *
     * @param message the message to remove
     * @return true if the message was removed
     */
    public boolean removeFromHam(String message) {
        if (message == null || message.isEmpty()) {
            return false;
        }
        String cleanMessage = cleanMessage(message);
        boolean removed = hamCorpus.remove(cleanMessage);
        if (removed) {
            saveCorpus(hamCorpusFile, hamCorpus);
            log.debug("Removed from ham corpus: {}", cleanMessage);
        }
        return removed;
    }

    /**
     * Get an unmodifiable view of the spam corpus.
     *
     * @return unmodifiable list of spam messages
     */
    public List<String> getSpamCorpusView() {
        return Collections.unmodifiableList(spamCorpus);
    }

    /**
     * Get an unmodifiable view of the ham corpus.
     *
     * @return unmodifiable list of ham messages
     */
    public List<String> getHamCorpusView() {
        return Collections.unmodifiableList(hamCorpus);
    }

    /**
     * Clear all entries from the spam corpus.
     */
    public void clearSpamCorpus() {
        spamCorpus.clear();
        saveCorpus(spamCorpusFile, spamCorpus);
        log.debug("Cleared spam corpus");
    }

    /**
     * Clear all entries from the ham corpus.
     */
    public void clearHamCorpus() {
        hamCorpus.clear();
        saveCorpus(hamCorpusFile, hamCorpus);
        log.debug("Cleared ham corpus");
    }

    /**
     * Clean a message by removing any score suffix patterns like " (0.85)".
     */
    private String cleanMessage(String message) {
        // Remove spam score suffix if present (e.g., " (0.85)" at the end)
        return message.replaceAll("\\s*\\([0-9.]+\\)$", "").trim();
    }

    private void appendToCorpus(String message, List<String> corpus, Path corpusFile) {
        if (corpus.contains(message)) {
            return; // Already in corpus
        }

        corpus.add(message);
        saveCorpus(corpusFile, corpus);
    }

    private void loadCorpus(Path file, List<String> corpus) throws IOException {
        corpus.clear();

        if (!Files.exists(file)) {
            // Create empty file
            Files.createFile(file);
            return;
        }

        List<String> lines = Files.readAllLines(file);
        for (String line : lines) {
            String trimmed = line.trim();
            if (!trimmed.isEmpty()) {
                corpus.add(trimmed);
            }
        }
    }

    private void saveCorpus(Path file, List<String> corpus) {
        try {
            Files.write(file, corpus,
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING,
                StandardOpenOption.WRITE);
        } catch (IOException e) {
            log.error("Failed to save corpus file: {}", file, e);
        }
    }

    private static void ensureDir(Path dir) throws IOException {
        if (!Files.exists(dir)) {
            Files.createDirectories(dir);
        }
        if (!Files.isDirectory(dir)) {
            throw new IOException("Not a directory: " + dir);
        }
    }

    private static Path resolveDataDir() {
        Path rlHome = null;
        try {
            java.io.File dir = RuneLite.RUNELITE_DIR;
            if (dir != null) {
                rlHome = dir.toPath();
            }
        } catch (Throwable ignored) {
        }
        if (rlHome == null) {
            rlHome = Paths.get(System.getProperty("user.home", ".")).resolve(".runelite");
        }
        // Use same directory as SpamFilterPlugin for compatibility
        return rlHome.resolve(SPAMFILTER_DIR);
    }
}

package com.modernchat.service;

import com.modernchat.common.ChatMessageBuilder;
import com.modernchat.common.NotificationService;
import com.modernchat.common.TutorialState;
import com.modernchat.event.ChatMessageSentEvent;
import com.modernchat.event.ChatPrivateMessageSentEvent;
import com.modernchat.event.ChatToggleEvent;
import com.modernchat.event.FeatureStoppedEvent;
import com.modernchat.event.TabChangeEvent;
import com.modernchat.feature.ChatRedesignFeature;
import com.modernchat.overlay.ChatOverlay;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.util.Timer;
import java.util.TimerTask;

@Slf4j
@Singleton
public class TutorialService implements ChatService
{
    @Inject private EventBus eventBus;
    @Inject private NotificationService notificationService;
    @Inject private ChatOverlay chatOverlay;

    @Getter private TutorialState state = TutorialState.NOT_STARTED;

    @Override
    public void startUp() {
        eventBus.register(this);

        if (state == TutorialState.NOT_STARTED) {
            log.debug("Tutorial awaiting toggle event received, starting tutorial");
            notificationService.pushChatMessage(new ChatMessageBuilder()
                .append(
                    "This will guide you through some new chat features. " +
                    "To start, please make sure your chat is visible, press ")
                .append(Color.ORANGE, "Enter").
                append(" to open the chat."));

            state = TutorialState.AWAITING_TOGGLE;
        } else {
            log.warn("Unexpected tutorial state: {}", state);
        }
    }

    @Override
    public void shutDown() {
        eventBus.unregister(this);

        state = TutorialState.NOT_STARTED;
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        if (!chatOverlay.isEnabled())
            shutDown();
    }

    @Subscribe
    public void onChatToggleEvent(ChatToggleEvent e) {
        if (e.isHidden())
            return; // Ignore if chat is hidden, tutorial requires chat to be visible

        if (state == TutorialState.AWAITING_TOGGLE) {
            log.debug("Chat toggle event received, proceeding with tutorial");
            if (chatOverlay.getTabOrder().size() > 1) {
                notificationService.pushChatMessage(new ChatMessageBuilder()
                    .append("Try selecting a ")
                    .append(Color.ORANGE, "chat tab at the top")
                    .append(" to switch to chat mode channels."));

                state = TutorialState.AWAITING_TAB_SWITCH;
            } else {
                notificationService.pushChatMessage(new ChatMessageBuilder()
                    .append("At the ")
                    .append(Color.ORANGE, "top of the chat")
                    .append(" you will see chat mode tabs open when you join them. Now lets try ")
                    .append(Color.ORANGE, "sending a message in chat"));
            }
        } else {
            log.warn("Unexpected tutorial state: {}", state);
        }
    }

    @Subscribe
    public void onTabChangeEvent(TabChangeEvent e) {
        if (state == TutorialState.AWAITING_TAB_SWITCH) {
            log.debug("Chat tab switched, proceeding with tutorial");
            new Timer().schedule(new TimerTask()
            {
                @Override
                public void run() {
                    notificationService.pushChatMessage(new ChatMessageBuilder()
                        .append("Nice! Now try ")
                        .append(Color.ORANGE, "sending a message")
                        .append(" in a chat mode channel by typing into the input box and pressing ")
                        .append(Color.ORANGE, "Enter"));

                    state = TutorialState.AWAITING_CHAT_SEND;
                }
            }, 400);
        } else if (state == TutorialState.AWAITING_PRIVATE_CHAT && e.getNewTab().isPrivate()) {
            log.debug("Private chat sent, completing tutorial");
            new Timer().schedule(new TimerTask() {
                @Override
                public void run() {
                    notificationService.pushChatMessage(new ChatMessageBuilder()
                        .append("Congratulations! You have completed the Modern Chat tutorial. " +
                            "Check out the settings to customize your chat experience even more! Some features to note are: ")
                        .append(Color.ORANGE, "resizeable chat").append(", ")
                        .append(Color.ORANGE, "moveable tabs").append(", ")
                        .append(Color.ORANGE, "input selection").append(", ")
                        .append(Color.ORANGE, "input navigation").append(", ")
                        .append(Color.ORANGE, "chat history (shift up/down)")
                        .append(" and much more!"));

                    state = TutorialState.COMPLETED;
                    shutDown();
                }
            }, 600);
        } else {
            log.warn("Unexpected tutorial state: {}", state);
        }
    }

    @Subscribe
    public void onChatMessageSentEvent(ChatMessageSentEvent e) {
        if (state == TutorialState.AWAITING_CHAT_SEND) {
            log.debug("Chat message sent, proceeding with tutorial");
            new Timer().schedule(new TimerTask() {
                @Override
                public void run() {
                    notificationService.pushChatMessage(new ChatMessageBuilder()
                        .append("Great! Now try ")
                        .append(Color.ORANGE, "opening a private channel")
                        .append(" to message another player, by ")
                        .append(Color.ORANGE, "right-clicking")
                        .append(" on their name in chat, name in friends list or character in the world, you will see the ")
                        .append(Color.ORANGE, "Chat with")
                        .append(" or ")
                        .append(Color.ORANGE, "Message")
                        .append(" option appear."));

                    state = TutorialState.AWAITING_PRIVATE_CHAT;
                }
            }, 600);
        } else {
            log.warn("Unexpected tutorial state: {}", state);
        }
    }

    @Subscribe
    public void onChatPrivateMessageSentEvent(ChatPrivateMessageSentEvent e) {

    }

    @Subscribe
    public void onFeatureStoppedEvent(FeatureStoppedEvent e) {
        if (!e.getFeature().getClass().equals(ChatRedesignFeature.class))
            return;

        log.debug("Feature stopped, resetting tutorial state");
        state = TutorialState.NOT_STARTED;
        shutDown();
        notificationService.pushChatMessage(new ChatMessageBuilder()
            .append("Tutorial has ended."));
    }
}

package com.modernchat.service.filter;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.modernchat.ModernChatConfig;
import com.modernchat.service.ChatService;
import com.modernchat.service.MessageFilter;
import com.modernchat.util.ConfigUtil;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.util.Text;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.lang.reflect.Type;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/**
 * Built-in filter that replicates the Area Mute plugin's filtering logic.
 * Blocks public/autotyper messages from players in muted regions.
 * Reads configuration from the "areamute" config group via ConfigManager.
 */
@Slf4j
@Singleton
public class AreaMutePluginFilter implements MessageFilter, ChatService {
    private static final String CONFIG_GROUP = "areamute";
    private static final String PLUGIN_NAME = "Area Mute";
    private static final Type REGIONS_TOKEN = new TypeToken<HashSet<Integer>>() {}.getType();

    private static final Set<ChatMessageType> FILTERED_TYPES = EnumSet.of(
        ChatMessageType.PUBLICCHAT,
        ChatMessageType.AUTOTYPER
    );

    @Inject private Client client;
    @Inject private ConfigManager configManager;
    @Inject private PluginManager pluginManager;
    @Inject private EventBus eventBus;
    @Inject private Gson gson;
    @Inject private ModernChatConfig modernChatConfig;

    private volatile boolean pluginEnabled = false;
    private volatile boolean filterSelf = false;
    private volatile boolean filterFriends = false;
    private volatile boolean filterClanMates = false;
    private volatile boolean filterFriendChat = false;
    private final Set<Integer> mutedRegions = new HashSet<>();

    // Cache of message ID -> should block
    private final LinkedHashMap<Integer, Boolean> chatCache = new LinkedHashMap<>() {
        private static final int MAX_ENTRIES = 2000;

        @Override
        protected boolean removeEldestEntry(Map.Entry<Integer, Boolean> eldest) {
            return size() > MAX_ENTRIES;
        }
    };

    @Override
    public boolean isEnabled() {
        return modernChatConfig.filters_AreaMuteEnabled();
    }

    @Override
    public void startUp() {
        eventBus.register(this);
        checkPluginEnabled();
        if (pluginEnabled) {
            refreshConfig();
        }
    }

    @Override
    public void shutDown() {
        eventBus.unregister(this);
        chatCache.clear();
        mutedRegions.clear();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged e) {
        if (CONFIG_GROUP.equals(e.getGroup())) {
            refreshConfig();
        }
    }

    @Subscribe
    public void onPluginChanged(PluginChanged e) {
        if (PLUGIN_NAME.equals(e.getPlugin().getName())) {
            checkPluginEnabled();
            if (e.isLoaded()) {
                refreshConfig();
            }
        }
    }

    @Override
    public @Nullable String apply(ChatMessage message, String currentText) {
        if (!pluginEnabled || mutedRegions.isEmpty())
            return currentText;

        ChatMessageType type = message.getType();
        if (!FILTERED_TYPES.contains(type))
            return currentText;

        String name = Text.removeTags(message.getName());
        int messageId = message.getMessageNode().getId();

        // Find the player actor to get their region
        Player actor = findPlayer(name);

        if (shouldFilter(actor, name)) {
            chatCache.put(messageId, true);
            return null;
        }

        return currentText;
    }

    private @Nullable Player findPlayer(String name) {
        for (Player p : client.getTopLevelWorldView().players()) {
            if (name.equalsIgnoreCase(p.getName()))
                return p;
        }

        Player local = client.getLocalPlayer();
        if (local != null && name.equalsIgnoreCase(local.getName()))
            return local;

        return null;
    }

    private boolean shouldFilter(@Nullable Player actor, String name) {
        Player local = client.getLocalPlayer();
        if (local == null)
            return false;

        int region = local.getWorldLocation().getRegionID();
        if (actor != null) {
            region = actor.getWorldLocation().getRegionID();
        }

        if (actor == local && !filterSelf)
            return false;

        if (!filterFriends && client.isFriended(name, false))
            return false;

        if (!filterFriendChat && isFriendsChatMember(name))
            return false;

        if (!filterClanMates && isClanChatMember(name))
            return false;

        return mutedRegions.contains(region);
    }

    private boolean isFriendsChatMember(String name) {
        FriendsChatManager friendsChatManager = client.getFriendsChatManager();
        return friendsChatManager != null && friendsChatManager.findByName(name) != null;
    }

    private boolean isClanChatMember(String name) {
        ClanChannel clanChannel = client.getClanChannel();
        if (clanChannel != null && clanChannel.findMember(name) != null)
            return true;

        clanChannel = client.getGuestClanChannel();
        return clanChannel != null && clanChannel.findMember(name) != null;
    }

    private void checkPluginEnabled() {
        pluginEnabled = false;
        for (Plugin plugin : pluginManager.getPlugins()) {
            if (PLUGIN_NAME.equals(plugin.getName()) && pluginManager.isPluginEnabled(plugin)) {
                pluginEnabled = true;
                break;
            }
        }
        log.debug("AreaMute plugin enabled check: {}", pluginEnabled);
    }

    private void refreshConfig() {
        filterSelf = ConfigUtil.getBool(configManager, CONFIG_GROUP, "filterSelf", false);
        filterFriends = ConfigUtil.getBool(configManager, CONFIG_GROUP, "filterFriends", false);
        filterClanMates = ConfigUtil.getBool(configManager, CONFIG_GROUP, "filterClanMates", false);
        filterFriendChat = ConfigUtil.getBool(configManager, CONFIG_GROUP, "filterCC", false);
        loadRegions();

        log.debug("AreaMute config refreshed: filterSelf={}, regions={}", filterSelf, mutedRegions.size());
    }

    private void loadRegions() {
        mutedRegions.clear();
        String regionsJson = ConfigUtil.getString(configManager, CONFIG_GROUP, "regions", "[]");
        try {
            Set<Integer> parsed = gson.fromJson(regionsJson, REGIONS_TOKEN);
            if (parsed != null) {
                mutedRegions.addAll(parsed);
            }
        } catch (Exception e) {
            log.warn("Failed to parse areamute regions: {}", regionsJson, e);
        }
    }
}

package com.modernchat.service.filter;

import com.modernchat.ModernChatConfig;
import com.modernchat.service.ChatService;
import com.modernchat.service.MessageFilter;
import com.modernchat.util.ConfigUtil;
