import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.regex.MatchResult;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Built-in filter that replicates RuneLite's ChatFilterPlugin filtering logic.
 * Reads configuration from the "chatfilter" config group via ConfigManager.
 */
@Slf4j
@Singleton
public class ChatFilterPluginFilter implements MessageFilter, ChatService {
    private static final String CONFIG_GROUP = "chatfilter";
    private static final String PLUGIN_NAME = "Chat Filter";
    static final String CENSOR_MESSAGE = "Hey, everyone, I just tried to say something very silly!";

    private static final Set<ChatMessageType> PLAYER_TYPES = EnumSet.of(
        ChatMessageType.PUBLICCHAT,
        ChatMessageType.MODCHAT,
        ChatMessageType.AUTOTYPER,
        ChatMessageType.PRIVATECHAT,
        ChatMessageType.MODPRIVATECHAT,
        ChatMessageType.FRIENDSCHAT,
        ChatMessageType.CLAN_CHAT,
        ChatMessageType.CLAN_GUEST_CHAT,
        ChatMessageType.CLAN_GIM_CHAT
    );

    private static final Set<ChatMessageType> GAME_TYPES = EnumSet.of(
        ChatMessageType.GAMEMESSAGE,
        ChatMessageType.ENGINE,
        ChatMessageType.FRIENDSCHATNOTIFICATION,
        ChatMessageType.ITEM_EXAMINE,
        ChatMessageType.NPC_EXAMINE,
        ChatMessageType.OBJECT_EXAMINE,
        ChatMessageType.SPAM,
        ChatMessageType.CLAN_MESSAGE,
        ChatMessageType.CLAN_GUEST_MESSAGE,
        ChatMessageType.CLAN_GIM_MESSAGE,
        ChatMessageType.NPC_SAY
    );

    private static final Set<ChatMessageType> COLLAPSIBLE_MESSAGETYPES = EnumSet.of(
        ChatMessageType.ENGINE,
        ChatMessageType.GAMEMESSAGE,
        ChatMessageType.ITEM_EXAMINE,
        ChatMessageType.NPC_EXAMINE,
        ChatMessageType.OBJECT_EXAMINE,
        ChatMessageType.SPAM,
        ChatMessageType.PUBLICCHAT,
        ChatMessageType.MODCHAT,
        ChatMessageType.NPC_SAY
    );

    @Inject private Client client;
    @Inject private ConfigManager configManager;
    @Inject private PluginManager pluginManager;
    @Inject private EventBus eventBus;
    @Inject private ModernChatConfig modernChatConfig;

    // Cached patterns
    private volatile List<Pattern> filteredPatterns = Collections.emptyList();
    private volatile List<Pattern> filteredNamePatterns = Collections.emptyList();

    // Cached config values
    private volatile String filterType = "CENSOR_WORDS";
    private volatile boolean filterFriends = false;
    private volatile boolean filterFriendsChat = false;
    private volatile boolean filterClanChat = false;
    private volatile boolean filterGameChat = false;
    private volatile boolean collapseGameChat = false;
    private volatile boolean collapsePlayerChat = false;
    private volatile int maxRepeatedPublicChats = 0;
    private volatile boolean stripAccents = false;
    private volatile boolean pluginEnabled = false;

    // Duplicate tracking
    private static class Duplicate {
        int messageId;
        int count;
    }

    private final LinkedHashMap<String, Duplicate> duplicateChatCache = new LinkedHashMap<>() {
        private static final int MAX_ENTRIES = 100;

        @Override
        protected boolean removeEldestEntry(Map.Entry<String, Duplicate> eldest) {
            return size() > MAX_ENTRIES;
        }
    };

    @Override
    public boolean isEnabled() {
        return modernChatConfig.filters_ChatFilterEnabled();
    }

    @Override
    public void startUp() {
        eventBus.register(this);
        checkPluginEnabled();
        if (pluginEnabled) {
            refreshConfig();
        }
    }

    @Override
    public void shutDown() {
        eventBus.unregister(this);
        filteredPatterns = Collections.emptyList();
        filteredNamePatterns = Collections.emptyList();
        duplicateChatCache.clear();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged e) {
        if (CONFIG_GROUP.equals(e.getGroup())) {
            refreshConfig();
        }
    }

    @Subscribe
    public void onPluginChanged(PluginChanged e) {
        if (PLUGIN_NAME.equals(e.getPlugin().getName())) {
            checkPluginEnabled();
            if (e.isLoaded()) {
                refreshConfig();
            }
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged e) {
        switch (e.getGameState()) {
            case CONNECTION_LOST:
            case HOPPING:
            case LOGGING_IN:
                duplicateChatCache.values().forEach(d -> d.messageId = -1);
                break;
        }
    }

    private void trackDuplicate(ChatMessage chatMessage) {
        if (!pluginEnabled)
            return;

        if (COLLAPSIBLE_MESSAGETYPES.contains(chatMessage.getType())) {
            int messageId = chatMessage.getMessageNode().getId();
            String key = chatMessage.getMessageNode().getName() + ":" + chatMessage.getMessageNode().getValue();
            Duplicate duplicate = duplicateChatCache.get(key);
            if (duplicate != null && duplicate.messageId == messageId) {
                return; // already tracked this message
            }
            duplicateChatCache.remove(key);
            if (duplicate == null) {
                duplicate = new Duplicate();
            }
            duplicate.count++;
            duplicate.messageId = messageId;
            duplicateChatCache.put(key, duplicate);
        }
    }

    @Override
    public @Nullable String apply(ChatMessage message, String currentText) {
        trackDuplicate(message);

        if (!pluginEnabled)
            return currentText;

        ChatMessageType type = message.getType();
        String name = message.getMessageNode().getName();
        int messageId = message.getMessageNode().getId();
        String result = currentText;
        boolean blockMessage = false;

        // Player message filtering
        if (PLAYER_TYPES.contains(type)) {
            if (canFilterPlayer(Text.sanitize(name))) {
                result = censorMessage(name, result);
                blockMessage = result == null;
            }
        }
        // Game message filtering
        else if (GAME_TYPES.contains(type)) {
            if (filterGameChat) {
                result = censorMessage(null, result);
                blockMessage = result == null;
            }
        }

        // Duplicate collapse
        boolean shouldCollapse = (type == ChatMessageType.PUBLICCHAT || type == ChatMessageType.MODCHAT)
            ? collapsePlayerChat
            : COLLAPSIBLE_MESSAGETYPES.contains(type) && collapseGameChat;

        if (!blockMessage && shouldCollapse) {
            Duplicate duplicateCacheEntry = duplicateChatCache.get(name + ":" + result);
            if (duplicateCacheEntry != null && duplicateCacheEntry.messageId != -1) {
                blockMessage = duplicateCacheEntry.messageId != messageId ||
                    ((type == ChatMessageType.PUBLICCHAT || type == ChatMessageType.MODCHAT) &&
                        maxRepeatedPublicChats > 0 && duplicateCacheEntry.count > maxRepeatedPublicChats);

                if (!blockMessage && duplicateCacheEntry.count > 1) {
                    result = result + " (" + duplicateCacheEntry.count + ")";
                }
            }
        }

        return blockMessage ? null : result;
    }

    private void checkPluginEnabled() {
        pluginEnabled = false;
        for (Plugin plugin : pluginManager.getPlugins()) {
            if (PLUGIN_NAME.equals(plugin.getName()) && pluginManager.isPluginEnabled(plugin)) {
                pluginEnabled = true;
                break;
            }
        }
        log.debug("ChatFilter plugin enabled check: {}", pluginEnabled);
    }

    private void refreshConfig() {
        filterType = ConfigUtil.getString(configManager, CONFIG_GROUP, "filterType", "CENSOR_WORDS");
        filterFriends = ConfigUtil.getBool(configManager, CONFIG_GROUP, "filterFriends", false);
        filterFriendsChat = ConfigUtil.getBool(configManager, CONFIG_GROUP, "filterClan", false);
        filterClanChat = ConfigUtil.getBool(configManager, CONFIG_GROUP, "filterClanChat", false);
        filterGameChat = ConfigUtil.getBool(configManager, CONFIG_GROUP, "filterGameChat", false);
        collapseGameChat = ConfigUtil.getBool(configManager, CONFIG_GROUP, "collapseGameChat", false);
        collapsePlayerChat = ConfigUtil.getBool(configManager, CONFIG_GROUP, "collapsePlayerChat", false);
        maxRepeatedPublicChats = ConfigUtil.getInt(configManager, CONFIG_GROUP, "maxRepeatedPublicChats", 0);
        stripAccents = ConfigUtil.getBool(configManager, CONFIG_GROUP, "stripAccents", false);

        updateFilteredPatterns();

        log.debug("ChatFilter config refreshed: filterType={}, filterGameChat={}, collapse={}/{}, patterns={}, namePatterns={}",
            filterType, filterGameChat, collapsePlayerChat, collapseGameChat,
            filteredPatterns.size(), filteredNamePatterns.size());
    }

    private boolean canFilterPlayer(String playerName) {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null)
            return false;

        boolean isMessageFromSelf = playerName.equals(localPlayer.getName());
        return !isMessageFromSelf &&
            (filterFriends || !client.isFriended(playerName, false)) &&
            (filterFriendsChat || !isFriendsChatMember(playerName)) &&
            (filterClanChat || !isClanChatMember(playerName));
    }

    private boolean isFriendsChatMember(String name) {
        FriendsChatManager friendsChatManager = client.getFriendsChatManager();
        return friendsChatManager != null && friendsChatManager.findByName(name) != null;
    }

    private boolean isClanChatMember(String name) {
        ClanChannel clanChannel = client.getClanChannel();
        if (clanChannel != null && clanChannel.findMember(name) != null)
            return true;

        clanChannel = client.getGuestClanChannel();
        return clanChannel != null && clanChannel.findMember(name) != null;
    }

    private @Nullable String censorMessage(@Nullable String username, String message) {
        String strippedMessage = Text.JAGEX_PRINTABLE_CHAR_MATCHER.retainFrom(message)
            .replace('\u00A0', ' ')
            .replace("<lt>", "<")
            .replace("<gt>", ">");
        String strippedAccents = stripAccentsIfEnabled(strippedMessage);

        if (username != null && isNameFiltered(username)) {
            switch (filterType) {
                case "CENSOR_WORDS":
                    return StringUtils.repeat('*', strippedMessage.length());
                case "CENSOR_MESSAGE":
                    return CENSOR_MESSAGE;
                case "REMOVE_MESSAGE":
                    return null;
            }
        }

        boolean filtered = false;
        for (Pattern pattern : filteredPatterns) {
            Matcher m = pattern.matcher(strippedAccents);
            StringBuilder sb = new StringBuilder();
            int idx = 0;

            while (m.find()) {
                switch (filterType) {
                    case "CENSOR_WORDS":
                        MatchResult matchResult = m.toMatchResult();
                        sb.append(strippedMessage, idx, matchResult.start())
                            .append(StringUtils.repeat('*', matchResult.group().length()));
                        idx = m.end();
                        filtered = true;
                        break;
                    case "CENSOR_MESSAGE":
                        return CENSOR_MESSAGE;
                    case "REMOVE_MESSAGE":
                        return null;
                }
            }
            sb.append(strippedMessage.substring(idx));

            strippedMessage = sb.toString();
            strippedAccents = stripAccentsIfEnabled(strippedMessage);
        }

        return filtered ? strippedMessage : message;
    }

    private boolean isNameFiltered(String playerName) {
        String sanitizedName = Text.standardize(playerName);
        for (Pattern pattern : filteredNamePatterns) {
            if (pattern.matcher(sanitizedName).find())
                return true;
        }
        return false;
    }

    private void updateFilteredPatterns() {
        List<Pattern> patterns = new ArrayList<>();
        List<Pattern> namePatterns = new ArrayList<>();

        String filteredWords = ConfigUtil.getString(configManager, CONFIG_GROUP, "filteredWords", "");
        String filteredRegex = ConfigUtil.getString(configManager, CONFIG_GROUP, "filteredRegex", "");
        String filteredNames = ConfigUtil.getString(configManager, CONFIG_GROUP, "filteredNames", "");

        // Words: CSV-separated, compiled with Pattern.quote
        Text.fromCSV(filteredWords).stream()
            .map(this::stripAccentsIfEnabled)
            .map(s -> compilePattern(Pattern.quote(s)))
            .filter(Objects::nonNull)
            .forEach(patterns::add);

        // Regex: newline-separated
        splitNewlines(filteredRegex).stream()
            .map(this::stripAccentsIfEnabled)
            .map(ChatFilterPluginFilter::compilePattern)
            .filter(Objects::nonNull)
            .forEach(patterns::add);

        // Names: newline-separated regex patterns
        splitNewlines(filteredNames).stream()
            .map(this::stripAccentsIfEnabled)
            .map(ChatFilterPluginFilter::compilePattern)
            .filter(Objects::nonNull)
            .forEach(namePatterns::add);

        filteredPatterns = patterns;
        filteredNamePatterns = namePatterns;
    }

    private String stripAccentsIfEnabled(String input) {
        return stripAccents ? StringUtils.stripAccents(input) : input;
    }

    private static @Nullable Pattern compilePattern(String pattern) {
        try {
            return Pattern.compile(pattern, Pattern.CASE_INSENSITIVE);
        } catch (PatternSyntaxException ex) {
            return null;
        }
    }

    private static List<String> splitNewlines(String input) {
        if (input == null || input.isEmpty())
            return Collections.emptyList();

        List<String> result = new ArrayList<>();
        for (String line : input.split("\n")) {
            String trimmed = line.trim();
            if (!trimmed.isEmpty()) {
                result.add(trimmed);
            }
        }
        return result;
    }

}

package com.modernchat.service.filter;

import com.modernchat.ModernChatConfig;
import com.modernchat.service.MessageFilter;
import com.modernchat.service.SpamFilterService;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.ChatMessage;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Built-in filter that consults the user-managed spam corpus from {@link SpamFilterService}.
 * Messages whose raw text matches a "Mark spam" entry are blocked from rendering, unless the
 * same text is also present in the ham corpus (acting as an explicit whitelist override).
 *
 * Match is performed against the original {@link ChatMessage#getMessage()} so that earlier
 * filter stages (e.g. censoring) cannot mask a previously-marked message.
 */
@Slf4j
@Singleton
public class SpamCorpusFilter implements MessageFilter {

    @Inject private SpamFilterService spamFilterService;
    @Inject private ModernChatConfig config;

    @Override
    public boolean isEnabled() {
        return config.filters_SpamCorpusEnabled();
    }

    @Override
    public @Nullable String apply(ChatMessage message, String currentText) {
        String rawText = message.getMessage();
        if (rawText == null || rawText.isEmpty())
            return currentText;

        if (spamFilterService.isMarkedHam(rawText))
            return currentText;

        if (spamFilterService.isMarkedSpam(rawText)) {
            log.debug("Blocking message marked as spam: {}", rawText);
            return null;
        }
        return currentText;
    }
}

package com.modernchat.service.filter;

import com.modernchat.ModernChatConfig;
import com.modernchat.service.MessageFilter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.VarbitID;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumSet;
import java.util.Set;

/**
 * Honours OSRS's vanilla chat-tab filter dropdown. Modern Chat overlays its own UI, which
 * means vanilla's per-tab "On / Filtered / Off" selector no longer takes effect — flavor-text
 * spam (e.g. "You catch a shrimp.") still renders even when the player has set the Game tab
 * to Filtered. This filter reads the relevant varbits and reproduces the vanilla behavior.
 *
 * Game tab varbit ({@link VarbitID#GAME_FILTER}):
 *   0 = On       — show everything
 *   1 = Filtered — hide {@link ChatMessageType#SPAM} (flavor text)
 *   2 = Off      — hide all game-channel message types
 */
@Slf4j
@Singleton
public class VanillaChatFilter implements MessageFilter {

    private static final Set<ChatMessageType> GAME_TYPES = EnumSet.of(
        ChatMessageType.GAMEMESSAGE,
        ChatMessageType.ENGINE,
        ChatMessageType.ITEM_EXAMINE,
        ChatMessageType.NPC_EXAMINE,
        ChatMessageType.OBJECT_EXAMINE,
        ChatMessageType.SPAM,
        ChatMessageType.NPC_SAY
    );

    @Inject private Client client;
    @Inject private ModernChatConfig config;

    @Override
    public boolean isEnabled() {
        return config.filters_VanillaTabFilterEnabled();
    }

    @Override
    public @Nullable String apply(ChatMessage message, String currentText) {
        ChatMessageType type = message.getType();

        int gameMode = client.getVarbitValue(VarbitID.GAME_FILTER);
        if (gameMode == 2 && GAME_TYPES.contains(type)) {
            return null;
        }
        if (gameMode >= 1 && type == ChatMessageType.SPAM) {
            return null;
        }

        return currentText;
    }
}

package com.modernchat.util;

import com.modernchat.common.ChatMessageBuilder;
import com.modernchat.common.ChatMode;
import com.modernchat.common.MessageLine;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.widgets.Widget;
import lombok.Value;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

import javax.annotation.Nullable;
import java.awt.Color;
import java.awt.Toolkit;
import java.awt.datatransfer.Clipboard;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ChatUtil
{
    public static final AtomicBoolean LEGACY_CHAT_HIDDEN = new AtomicBoolean(false);
    public static final String MODERN_CHAT_TAG = "[ModernChat]";
    public static final String COMMAND_MODE_MESSAGE = "Command Mode (Modern chat will be restored once you send or cancel the command)";

    private static final Pattern IMG_TAG_PATTERN = Pattern.compile("<img=(\\d+)>");

    @Value
    public static class SenderReceiver {
        String senderName;
        String receiverName;
        int senderIconId; // -1 if none (first icon when multiple)
        List<Integer> senderIconIds; // all icons in order, empty if none
    }

    public static int extractIconId(@Nullable String name) {
        if (name == null || name.isEmpty()) return -1;
        Matcher m = IMG_TAG_PATTERN.matcher(name);
        return m.find() ? Integer.parseInt(m.group(1)) : -1;
    }

    public static List<Integer> extractIconIds(@Nullable String name) {
        if (name == null || name.isEmpty()) return List.of();
        List<Integer> ids = null;
        Matcher m = IMG_TAG_PATTERN.matcher(name);
        while (m.find()) {
            if (ids == null) ids = new ArrayList<>();
            ids.add(Integer.parseInt(m.group(1)));
        }
        return ids == null ? List.of() : ids;
    }

    /**
     * Strips formatting tags the way the Force Recolor plugin's removeMostTags does:
     * every tag is removed EXCEPT &lt;lt&gt;, &lt;gt&gt; and &lt;img=N&gt; (case-sensitive,
     * digits only), and NBSP (U+00A0) is then normalized to a regular space - the original
     * plugin appends that replace so multi-word patterns still match NBSP-separated text.
     * Force Recolor patterns are built from Text.escapeJagex'd text, so the surviving
     * lt/gt entities line up with the escaped pattern text when matching.
     */
    public static String removeMostTags(@Nullable String s) {
        String stripped = stripTags(s, false);
        if (stripped == null || stripped.isEmpty()) return stripped;
        return stripped.replace('\u00A0', ' ');
    }

    /**
     * Strips only color tags (&lt;col=...&gt;, &lt;colNORMAL&gt;, &lt;/col&gt;) so an outer
     * color wrapper actually wins; all other tags (&lt;img=N&gt;, &lt;lt&gt;, &lt;gt&gt;,
     * &lt;br&gt;, ...) are preserved.
     */
    public static String removeColorTags(@Nullable String s) {
        return stripTags(s, true);
    }

    private static String stripTags(@Nullable String s, boolean colorTagsOnly) {
        if (s == null || s.isEmpty() || s.indexOf('<') < 0) return s;

        StringBuilder out = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); ) {
            char ch = s.charAt(i);
            if (ch != '<') {
                out.append(ch);
                i++;
                continue;
            }

            int j = s.indexOf('>', i + 1);
            if (j < 0) {
                // Unterminated tag: keep the remainder as-is. The original Force Recolor
                // plugin strips tags with a regex that requires a closing '>', so
                // unterminated text is never consumed as a tag there either.
                out.append(s, i, s.length());
                break;
            }

            boolean keep;
            if (colorTagsOnly) {
                // Match parseRich's case-insensitive color tag detection:
                // <col=HEX>, <colHEX>, <colNORMAL>, </col>
                keep = !(s.regionMatches(true, i + 1, "col", 0, 3)
                    || (j - i - 1 == 4 && s.regionMatches(true, i + 1, "/col", 0, 4)));
            } else {
                keep = isKeptMatchTag(s, i + 1, j);
            }
            if (keep) {
                out.append(s, i, j + 1);
            }
            i = j + 1;
        }
        return out.toString();
    }

    /**
     * Case-sensitive keep rule matching the original Force Recolor plugin's
     * removeMostTags: only &lt;lt&gt;, &lt;gt&gt; and &lt;img=N&gt; (N = digits) survive.
     * The tag body spans {@code [start, end)} of {@code s} (angle brackets excluded).
     */
    private static boolean isKeptMatchTag(String s, int start, int end) {
        int len = end - start;
        if (len == 2) {
            return s.regionMatches(start, "lt", 0, 2) || s.regionMatches(start, "gt", 0, 2);
        }
        if (len > 4 && s.regionMatches(start, "img=", 0, 4)) {
            for (int k = start + 4; k < end; k++) {
                char c = s.charAt(k);
                if (c < '0' || c > '9') return false;
            }
            return true;
        }
        return false;
    }

    public static boolean isPrivateMessage(ChatMessageType t) {
        return t == ChatMessageType.PRIVATECHAT
            || t == ChatMessageType.PRIVATECHATOUT
            || t == ChatMessageType.MODPRIVATECHAT;
    }

    public static boolean isPlayerType(MenuAction t) {
        switch (t) {
            case PLAYER_FIRST_OPTION:
            case PLAYER_SECOND_OPTION:
            case PLAYER_THIRD_OPTION:
            case PLAYER_FOURTH_OPTION:
            case PLAYER_FIFTH_OPTION:
            case PLAYER_SIXTH_OPTION:
            case PLAYER_SEVENTH_OPTION:
            case PLAYER_EIGHTH_OPTION:
            case RUNELITE_PLAYER: // when a RL player-targeted entry is present
                return true;
            default:
                return false;
        }
    }

    public static ChatMode toChatMode(ChatMessageType t) {
        switch (t) {
            case PRIVATECHAT:
            case PRIVATECHATOUT:
            case MODPRIVATECHAT:
            case FRIENDNOTIFICATION:
                return ChatMode.PRIVATE;
            case CLAN_CHAT:
            case CLAN_MESSAGE:
                return ChatMode.CLAN_MAIN;
            case CLAN_GUEST_CHAT:
            case CLAN_GUEST_MESSAGE:
                return ChatMode.CLAN_GUEST;
            case CLAN_GIM_CHAT:
            case CLAN_GIM_FORM_GROUP:
            case CLAN_GIM_MESSAGE:
            case CLAN_GIM_GROUP_WITH:
                return ChatMode.CLAN_GIM;
            case FRIENDSCHAT:
            case FRIENDSCHATNOTIFICATION:
                return ChatMode.FRIENDS_CHAT;
            default:
                return ChatMode.PUBLIC;
        }
    }

    public static String extractNameFromMessage(String line) {
        return extractNameFromMessage(line, null);
    }

    public static String extractNameFromMessage(String line, String orDefault) {
        if (line == null || line.isEmpty()) {
            return orDefault;
        }

        int idx = line.indexOf(':');
        if (idx < 0) {
            return orDefault; // No colon found, cannot extract name
        }

        String name = line.substring(0, idx).trim();
        if (name.isEmpty()) {
            return orDefault; // Empty name
        }

        return name;
    }

    public static List<String> chunk(String s, int limit) {
        if (limit <= 0 || s == null || s.isEmpty()) return List.of(s == null ? "" : s);
        List<String> out = new ArrayList<>((s.length() + limit - 1) / limit);
        Matcher m = Pattern.compile("(?s).+" + limit + "}").matcher(s);
        while (m.find()) out.add(m.group());
        return out;
    }

    public static Optional<String> getClipboardText() {
        try {
            Clipboard cb = Toolkit.getDefaultToolkit().getSystemClipboard();
            Transferable t = cb.getContents(null);
            if (t != null && t.isDataFlavorSupported(DataFlavor.stringFlavor)) {
                return Optional.of((String) t.getTransferData(DataFlavor.stringFlavor));
            }
        } catch (Exception ex) {
            // UnsupportedFlavorException | IOException | IllegalStateException (clipboard busy)
        }
        return Optional.empty();
    }

    public static boolean isClanMessage(ChatMessageType type) {
        return type == ChatMessageType.CLAN_CHAT
            || type == ChatMessageType.CLAN_MESSAGE
            || type == ChatMessageType.CLAN_GUEST_CHAT
            || type == ChatMessageType.CLAN_GUEST_MESSAGE
            || type == ChatMessageType.CLAN_GIM_CHAT
            || type == ChatMessageType.CLAN_GIM_FORM_GROUP
            || type == ChatMessageType.CLAN_GIM_MESSAGE
            || type == ChatMessageType.CLAN_GIM_GROUP_WITH;
    }

    public static boolean isFriendsChatMessage(ChatMessageType type) {
        return type == ChatMessageType.FRIENDSCHAT
            || type == ChatMessageType.FRIENDSCHATNOTIFICATION;
    }

    public static SenderReceiver getSenderAndReceiver(ChatMessage msg, String localPlayerName) {
        String receiverName = null;
        String senderName = msg.getSender();
        String name = msg.getName();
        ChatMessageType type = msg.getType();

        // Extract icon IDs from the raw name *before* stripping tags
        List<Integer> senderIconIds = List.of();

        if (type == ChatMessageType.PRIVATECHATOUT) {
            // For outgoing PMs, the "name" is the receiver - no sender icon
            receiverName = name != null ? Text.removeTags(name) : null;
            senderName = "You";
        }
        else if (type == ChatMessageType.PRIVATECHAT) {
            // For incoming PMs, the "name" is the sender - extract their icons
            senderIconIds = extractIconIds(name);
            receiverName = localPlayerName;
            senderName = name != null ? Text.removeTags(name) : null;
        }
        else if (ChatUtil.isClanMessage(type) || ChatUtil.isFriendsChatMessage(type)) {
            senderIconIds = extractIconIds(name);
            senderName = name != null ? Text.removeTags(name) : null;
        }
        else if (senderName == null) {
            senderIconIds = extractIconIds(name);
            senderName = name != null ? Text.removeTags(name) : null;
        }
        else {
            senderIconIds = extractIconIds(senderName);
            senderName = Text.removeTags(senderName);
        }

        if (receiverName == null) {
            receiverName = localPlayerName;
        }

        int senderIconId = senderIconIds.isEmpty() ? -1 : senderIconIds.get(0);
        return new SenderReceiver(senderName, receiverName, senderIconId, List.copyOf(senderIconIds));
    }

    public static String getCustomPrefix(ChatMessage msg) {
        ChatMessageType type = msg.getType();
        if (type == ChatMessageType.PRIVATECHATOUT) {
            return "";
        }
        else if (type == ChatMessageType.PRIVATECHAT) {
            return "";
        }
        else if (ChatUtil.isClanMessage(type) || ChatUtil.isFriendsChatMessage(type)) {
            return msg.getSender() != null ? "(" + msg.getSender() + ") " : "";
        }
        return "";
    }

    public static int getModImageId(String msg) {
        if (msg == null || msg.isEmpty())
            return -1;
        String idStr = msg.replace("IMG:", "");
        try {
            return Integer.parseInt(idStr);
        } catch (NumberFormatException e) {
            // Ignore and return default
        }
        return -1; // Default icon ID if not found
    }

    public static @Nullable MessageLine createMessageLine(ChatMessage e, Client client) {
        return createMessageLine(e, client, true);
    }

    public static @Nullable MessageLine createMessageLine(ChatMessage e, Client client, boolean requireLocalPlayer) {
        return createMessageLine(e, client, requireLocalPlayer, null);
    }

    /** Pattern to detect ChatFilterPlugin's collapse suffix like " (2)", " (15)" etc. */
    private static final Pattern COLLAPSE_PATTERN = Pattern.compile(" \\(\\d+\\)$");

    /** Message types that ChatFilterPlugin considers collapsible (game message types) */
    private static final Set<ChatMessageType> COLLAPSIBLE_MESSAGETYPES = EnumSet.of(
        ChatMessageType.ENGINE,
        ChatMessageType.GAMEMESSAGE,
        ChatMessageType.ITEM_EXAMINE,
        ChatMessageType.NPC_EXAMINE,
        ChatMessageType.OBJECT_EXAMINE,
        ChatMessageType.SPAM,
        ChatMessageType.PUBLICCHAT,
        ChatMessageType.MODCHAT,
        ChatMessageType.NPC_SAY
    );

    /**
     * Create a MessageLine from a ChatMessage, optionally using a filtered message text.
     *
     * @param e the chat message event
     * @param client the game client
     * @param requireLocalPlayer whether to require local player info
     * @param filteredMessage optional filtered message text (from chat filter plugins), or null to use original
     */
    public static @Nullable MessageLine createMessageLine(ChatMessage e, Client client, boolean requireLocalPlayer, @Nullable String filteredMessage) {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null && requireLocalPlayer)
            return null;

        String localPlayerName = "";
        if (localPlayer != null) {
            localPlayerName = localPlayer.getName();
            if (StringUtil.isNullOrEmpty(localPlayerName) && requireLocalPlayer)
                return null;
        }

        // Use local system time so timestamps reflect the player's clock, not the server's
        long timestamp = System.currentTimeMillis();

        SenderReceiver senderReceiver = ChatUtil.getSenderAndReceiver(e, localPlayerName);

        ChatMessageType type = e.getType();
        String originalMsg = e.getMessage();
        // Use filtered message if provided, otherwise use original
        String msg = filteredMessage != null ? filteredMessage : originalMsg;
        String[] params = msg.split("\\|", 3);
        String receiverName = senderReceiver.getReceiverName();
        String senderName = senderReceiver.getSenderName();
        int senderIconId = senderReceiver.getSenderIconId();
        String prefix = ChatUtil.getCustomPrefix(e);

        if (type == ChatMessageType.DIALOG) {
            senderName = ColorUtil.wrapWithColorTag(params.length > 1 ? params[params.length - 2] : senderName, Color.CYAN);
        }

        ChatMessageBuilder builder = new ChatMessageBuilder();

        if (!StringUtil.isNullOrEmpty(senderName)) {
            // Render account-type icons (ironman, leagues, etc.) before the sender name.
            // senderName itself stays tag-free - it is used for tab keys and target names.
            for (int iconId : senderReceiver.getSenderIconIds()) {
                builder.img(iconId);
            }
            builder.append(senderName, false).append(": ");
        }

        String message = msg;
        if (params.length > 1) {
            int icon = ChatUtil.getModImageId(params[0]);
            if (icon != -1) {
                builder.img(icon);
            }

            // message should always be last
            message = params[params.length - 1];
        }

        builder.append(message, false);

        // Generate duplicate key from name + original message (for collapse detection)
        String duplicateKey = e.getName() + ":" + originalMsg;

        // Check if the filtered message has a collapse suffix like " (2)"
        // Only detect collapse for COLLAPSIBLE_MESSAGETYPES (game message types)
        boolean collapsed = filteredMessage != null && originalMsg != null
            && COLLAPSIBLE_MESSAGETYPES.contains(type)
            && COLLAPSE_PATTERN.matcher(filteredMessage).find()
            && !originalMsg.equals(filteredMessage); // only if filtered differs from original

        return new MessageLine(builder.build(), type, timestamp, senderName, receiverName, prefix, duplicateKey, collapsed, senderIconId);
    }

    public static String getPrefix(ChatMessageType type) {
        String prefix = "";
        switch (type) {
            case PUBLICCHAT:
            case PRIVATECHAT:
            case PRIVATECHATOUT:
            case FRIENDSCHAT:
            case FRIENDSCHATNOTIFICATION:
            case FRIENDNOTIFICATION:
            case AUTOTYPER:
                break;
            case CLAN_CHAT:
            case CLAN_GIM_FORM_GROUP:
            case CLAN_GUEST_CHAT:
            case CLAN_GUEST_MESSAGE:
                prefix = "[Clan] ";
                break;
            case NPC_SAY:
            case DIALOG:
                prefix = "[NPC] ";
                break;
            case TRADE_SENT:
            case TRADEREQ:
                prefix = "[Trade] ";
                break;
            case SPAM:
                prefix = "[Spam] ";
                break;
            default:
                prefix = "[System] ";
        }
        return prefix;
    }

    public static void setChatHidden(Widget chat, boolean hidden) {
        chat.setHidden(hidden);
        LEGACY_CHAT_HIDDEN.set(hidden);
    }

    public static boolean isNpcMessage(ChatMessage e) {
        return isNpcMessage(e.getType());
    }

    public static boolean isNpcMessage(ChatMessageType type) {
        return type == ChatMessageType.NPC_SAY || type == ChatMessageType.DIALOG;
    }

    public static boolean isSpamMessage(ChatMessageType type) {
        return type == ChatMessageType.SPAM;
    }

    public static boolean isModernChatMessage(String message) {
        return message != null && Text.removeTags(message).startsWith(MODERN_CHAT_TAG);
    }

    public static boolean isIgnoredMessage(String line, ChatMessageType type) {
        return line.endsWith(ChatUtil.COMMAND_MODE_MESSAGE) && ChatUtil.isModernChatMessage(line);
    }
}

